insert into public.therapist_resources (slug, title, kind, summary, goal, audience, duration, body_md, fields, tags, created_at)
values
  ('screen-free-first-hour-morning-plan-sheet', 'Screen-Free First Hour Morning Plan Sheet', 'worksheet'::resource_kind, 'A planner for the first hour after waking without a phone, with what fills it instead and where the phone sleeps.', 'Use it to help a client who wakes into their feed design a first hour that belongs to them.', array['Adults', 'Teens']::text[], '15 minutes to plan, one week to try', 'Most clients who reach for the phone on waking describe the day starting in someone else''s agenda. The sheet asks where the phone will charge overnight, what the first three things in the hour will be, and what the client expects to miss. Keep the replacements concrete and small: a window, a kettle, a shower, a page of a book. Review after a week on how the hour felt and what crept back in, and treat a partial hour as data, not failure. Clients with early caregiving duties plan the hour around them rather than instead of them.', '[{"id": "f0", "type": "textarea", "label": "Where my phone will charge tonight, out of reach of the bed:"}, {"id": "f1", "type": "textarea", "label": "The first three things I will do in the hour instead:"}, {"id": "f2", "type": "textarea", "label": "What I am afraid I will miss by not looking:"}, {"id": "f3", "type": "textarea", "label": "A plan for the alarm clock, since my phone will not be it:"}, {"id": "f4", "type": "textarea", "label": "After a week: how the hour felt, and what crept back in:"}]'::jsonb, array['routines', 'habits', 'self-care']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('default-choices-for-tired-days-sheet', 'Default Choices for Tired Days Sheet', 'worksheet'::resource_kind, 'A sheet of pre-made decisions for low-energy days, so the client is not deciding dinner, clothes and plans when depleted.', 'Use it to take routine decisions off the table on the days a client has nothing left to decide with.', array['Adults', 'Teens']::text[], '25 minutes', 'Decision fatigue shows up as standing in front of the closet or the fridge for twenty minutes and then giving up. The sheet asks the client, on a good day, to set a default for each recurring choice: the tired-day outfit, the tired-day meal, the tired-day reply to invitations, the tired-day bedtime. Defaults are allowed to be plain. The work is in giving the tired self permission to use them without a fresh debate. Check back on which defaults got used and which were overruled, and what the overruling cost.', '[{"id": "f0", "type": "textarea", "label": "Decisions I find myself making over and over on tired days:"}, {"id": "f1", "type": "textarea", "label": "My default outfit for a tired day:"}, {"id": "f2", "type": "textarea", "label": "My default meal, and where its ingredients live:"}, {"id": "f3", "type": "textarea", "label": "My default answer to an invitation when I am depleted:"}, {"id": "f4", "type": "textarea", "label": "My default bedtime and wind-down on a tired day:"}, {"id": "f5", "type": "textarea", "label": "What I will say to myself when I use a default instead of deciding fresh:"}]'::jsonb, array['decisions', 'energy', 'planning']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('waiting-room-minutes-use-plan-sheet', 'Waiting Room Minutes Use Plan Sheet', 'worksheet'::resource_kind, 'A plan for the minutes spent waiting in offices, lines and lobbies, with a short menu of things to do besides scrolling.', 'Use it to turn the scattered waiting time in a client''s week into a few predictable minutes of rest or practice.', array['Adults', 'Teens']::text[], '15 minutes', 'Clients often say they have no time to practice a skill and then spend forty minutes a week in waiting rooms. The sheet asks them to estimate where their waiting happens, what they do with it now, and to build a three-item menu for it: a breathing practice, a page of reading, a look around the room, a text to someone they have been meaning to reach. The menu lives in a pocket or on a lock screen. Debrief on which item they actually used and whether the waiting felt different. Avoid turning it into another productivity demand.', '[{"id": "f0", "type": "textarea", "label": "Where I wait in a typical week, and for about how long:"}, {"id": "f1", "type": "textarea", "label": "What I usually do with waiting minutes now:"}, {"id": "f2", "type": "textarea", "label": "Three things I could do instead, each possible sitting in a chair:"}, {"id": "f3", "type": "textarea", "label": "Where my menu will live so I see it while waiting:"}, {"id": "f4", "type": "textarea", "label": "After a week: what I actually did while waiting, and how it felt:"}]'::jsonb, array['routines', 'mindfulness', 'planning']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('loud-open-office-focus-plan-sheet', 'Loud Open Office Focus Plan Sheet', 'worksheet'::resource_kind, 'A planner for working in a noisy shared space, covering sound, sight lines, signals to coworkers and recovery breaks.', 'Use it to help a client who comes home drained by an open office set up what they can control in it.', array['Adults']::text[], '20 minutes', 'Clients rarely separate the parts of a loud workplace they can change from the parts they cannot. The sheet sorts them: what can be changed about sound (headphones, a quieter corner, a booked room), sight lines (desk orientation, a plant, a screen), interruptions (a visible signal, a posted focus hour) and recovery (a walk, a stairwell minute). Ask the client to pick one change from each column for a week. Watch for the belief that asking for any of it marks them as difficult, and work that belief alongside the plan.', '[{"id": "f0", "type": "textarea", "label": "The parts of my workspace that drain me most:"}, {"id": "f1", "type": "textarea", "label": "One thing I could change about sound:"}, {"id": "f2", "type": "textarea", "label": "One thing I could change about what I see and who can see me:"}, {"id": "f3", "type": "textarea", "label": "A signal to coworkers that I am in a focus stretch, and how I will explain it:"}, {"id": "f4", "type": "textarea", "label": "Where I will take a five-minute recovery break, and when:"}, {"id": "f5", "type": "textarea", "label": "What I fear asking for any of this would say about me:"}]'::jsonb, array['stress', 'attention', 'planning']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('good-news-envy-sorting-sheet', 'Good News Envy Sorting Sheet', 'worksheet'::resource_kind, 'A sheet for the sting that arrives with a friend''s good news, sorting what the envy points at from what it says about the friendship.', 'Use it to help a client who feels small at others'' wins read the envy for information instead of shame.', array['Adults', 'Teens']::text[], '25 minutes', 'Envy is usually hidden from the therapist because the client is ashamed of it. Invite it in plainly. The sheet asks for the piece of news, the exact feeling, and then two sorts: what the envy says the client wants, and what the client fears it says about them as a friend. Most find the envy points at a real wish they have not been pursuing, and that wanting something is not the same as wishing the friend did not have it. Finish with one step on the wish and one way to show up for the friend.', '[{"id": "f0", "type": "textarea", "label": "The good news, and who it was about:"}, {"id": "f1", "type": "textarea", "label": "What I felt first, honestly:"}, {"id": "f2", "type": "textarea", "label": "What the envy says I want for myself:"}, {"id": "f3", "type": "textarea", "label": "What I was afraid the envy said about me as a friend:"}, {"id": "f4", "type": "textarea", "label": "One small step on my own wish this month:"}, {"id": "f5", "type": "textarea", "label": "One way I will show up for my friend about their news:"}]'::jsonb, array['self-criticism', 'relationships', 'values']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('magnification-and-minimization-balance-sheet', 'Magnification and Minimization Balance Sheet', 'cbt'::resource_kind, 'A two-column CBT sheet that catches a client blowing up setbacks while shrinking what went well, and rebalances the two.', 'Use it to show a client the binoculars effect: flaws through the magnifying end, strengths through the wrong end.', array['Adults', 'Teens']::text[], '20 minutes', 'This is the classic magnification and minimization distortion laid out so the client can see both halves at once. On the left they write the setback as their mind presents it; on the right, the same event as a neutral observer would describe it. Below, the same for something that went well that week, which is usually written small or forgotten. The sheet works best when the client reads both columns aloud and notices the size difference. Follow with one balanced sentence that holds both the setback and the win at their true size.', '[{"id": "f0", "type": "textarea", "label": "A setback this week, written the way my mind presented it:"}, {"id": "f1", "type": "textarea", "label": "The same event described by a neutral observer:"}, {"id": "f2", "type": "textarea", "label": "Something that went well this week that I nearly left off:"}, {"id": "f3", "type": "textarea", "label": "The same win described by someone who was rooting for me:"}, {"id": "f4", "type": "textarea", "label": "One balanced sentence that holds the setback and the win at their actual size:"}]'::jsonb, array['core CBT', 'thinking traps', 'cognitive restructuring']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('five-areas-situation-map-sheet', 'Five Areas Situation Map Sheet', 'cbt'::resource_kind, 'A five-areas map of one situation: the event, thoughts, feelings, body sensations and behavior, with arrows between them.', 'Use it to give a client a one-page picture of how thoughts, feelings, body and action feed each other in a hard moment.', array['Adults', 'Teens']::text[], '25 minutes', 'The five areas map is often the first CBT drawing a client sees, and drawing it together is better than handing it over. Take one recent moment and fill the five boxes in whatever order the client remembers them, then draw the arrows: which thought fed which feeling, which sensation fed which behavior, which behavior fed the next thought. Most clients see for the first time that there are several places to intervene, not just the thought. Ask which arrow feels easiest to cut and start there next session.', '[{"id": "f0", "type": "textarea", "label": "The situation: where I was, who was there, what happened:"}, {"id": "f1", "type": "textarea", "label": "Thoughts that went through my mind:"}, {"id": "f2", "type": "textarea", "label": "Feelings, each rated 0 to 100:"}, {"id": "f3", "type": "textarea", "label": "What I noticed in my body:"}, {"id": "f4", "type": "textarea", "label": "What I did, or stopped doing:"}, {"id": "f5", "type": "textarea", "label": "The arrow in my map that looks easiest to cut, and how:"}]'::jsonb, array['core CBT', 'formulation', 'psychoeducation']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('zig-zag-belief-debate-sheet', 'Zig-Zag Belief Debate Sheet', 'cbt'::resource_kind, 'A zig-zag sheet where the client argues for a healthier belief, attacks it as their old belief would, and answers the attack.', 'Use it to strengthen a new belief by letting the client rehearse the objections their old belief will raise.', array['Adults', 'Teens']::text[], '30 minutes', 'The zig-zag technique treats the new belief as something that has to survive cross-examination. The client writes the healthier belief at the top, then zig-zags down the page: an attack from the old belief in the left column, a rebuttal in the right, another attack, another rebuttal, until the attacks run thin. Keep the attacks honest and in the client''s real voice; weak attacks make the exercise feel rigged. Stop when the client can answer the strongest attack without hesitation, and note which attack was hardest for next time.', '[{"id": "f0", "type": "textarea", "label": "The healthier belief I am trying to strengthen:"}, {"id": "f1", "type": "textarea", "label": "Attack from my old belief, in its real voice:"}, {"id": "f2", "type": "textarea", "label": "My answer to that attack:"}, {"id": "f3", "type": "textarea", "label": "The old belief''s next attack:"}, {"id": "f4", "type": "textarea", "label": "My answer to that one:"}, {"id": "f5", "type": "textarea", "label": "The attack that was hardest to answer, and what I would need to answer it better:"}]'::jsonb, array['core CBT', 'core beliefs', 'cognitive restructuring']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('feared-fantasy-role-play-sheet', 'Feared Fantasy Role Play Sheet', 'cbt'::resource_kind, 'A role play script in which the client faces an imagined critic who says the worst out loud, and practices answering.', 'Use it to let a client meet their feared judgment in the room and discover it has less power when spoken.', array['Adults']::text[], 'Full session', 'The feared fantasy technique asks the client to imagine the harshest critic they can, one who says exactly what they fear others think. Play the critic first, using the client''s own words from the sheet, while the client answers with self-defense and, when ready, with acceptance of whatever is true. Then swap roles. Clients often laugh when the critic is finally spoken aloud; that is the moment to pause and ask what changed. Only use it once the client has some footing with self-compassion, and never in a first session.', '[{"id": "f0", "type": "textarea", "label": "What I am most afraid people think of me, in their exact words:"}, {"id": "f1", "type": "textarea", "label": "What the critic would say if they said it to my face:"}, {"id": "f2", "type": "textarea", "label": "My answer that defends myself:"}, {"id": "f3", "type": "textarea", "label": "My answer that accepts whatever part of it is true:"}, {"id": "f4", "type": "textarea", "label": "What it was like to hear the critic spoken aloud:"}, {"id": "f5", "type": "textarea", "label": "What I notice about how much power the words had, before and after:"}]'::jsonb, array['core CBT', 'self-criticism', 'cognitive restructuring']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('shame-attacking-small-experiment-sheet', 'Shame Attacking Small Experiment Sheet', 'cbt'::resource_kind, 'A planning sheet for a small, harmless act the client expects to be mortifying, with predictions and what actually happened.', 'Use it to test a client''s belief that looking foolish in public would be unbearable.', array['Adults', 'Teens']::text[], '30 minutes to plan, one outing to run', 'Shame attacking exercises are deliberate, harmless acts of mild foolishness: asking a stranger what month it is, wearing mismatched socks, singing a line in a store aisle. The client chooses one they rate as embarrassing but not harmful to anyone, predicts the reaction and their own distress, then runs it. Keep the act kind and legal, and never one that bothers others. The debrief compares prediction to outcome and asks how long the discomfort lasted. Clients often find no one noticed, which is its own lesson about the audience they carry.', '[{"id": "f0", "type": "textarea", "label": "The small, harmless act I will do:"}, {"id": "f1", "type": "textarea", "label": "What I predict people will do, and how embarrassed I predict I will feel (0 to 100):"}, {"id": "f2", "type": "textarea", "label": "What I predict I will do afterward:"}, {"id": "f3", "type": "textarea", "label": "What actually happened, and how embarrassed I actually felt:"}, {"id": "f4", "type": "textarea", "label": "How long the feeling lasted:"}, {"id": "f5", "type": "textarea", "label": "What this tells me about the audience I imagine watching me:"}]'::jsonb, array['core CBT', 'behavioral experiment', 'exposure']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('mind-as-a-word-machine-page', 'Mind as a Word Machine Page', 'act'::resource_kind, 'An ACT page that treats the mind as a machine that produces words all day, and practices catching the output without obeying it.', 'Use it to help a client see thoughts as a product of a busy machine rather than orders to follow.', array['Adults', 'Teens']::text[], '20 minutes', 'Ask the client to sit for two minutes and write down every word or phrase the mind produces, without sorting. Then read the list together as output from a machine that cannot stop: some of it useful, much of it noise, none of it a command. The page asks the client to label a few items as useful, noise or old favorites the machine has played for years. Clients with harsh inner critics find it easier to call the machine relentless than to call themselves relentless. Finish by asking what they would do today if the machine kept running and they went ahead anyway.', '[{"id": "f0", "type": "textarea", "label": "Two minutes of everything my mind produced, unsorted:"}, {"id": "f1", "type": "textarea", "label": "Which of these are useful, which are noise, and which are old favorites:"}, {"id": "f2", "type": "textarea", "label": "What the machine has been saying about me for years:"}, {"id": "f3", "type": "textarea", "label": "What I would do today if the machine kept running and I went ahead anyway:"}, {"id": "f4", "type": "textarea", "label": "A sentence I can use when I catch the machine running: I notice my word machine is saying…"}]'::jsonb, array['core ACT', 'defusion', 'self-talk']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('name-the-story-defusion-page', 'Name the Story Defusion Page', 'act'::resource_kind, 'A defusion page where the client gives their recurring self-story a title and greets it by name when it returns.', 'Use it to put a little distance between a client and the old story their mind tells, by naming it like a rerun.', array['Adults', 'Teens']::text[], '20 minutes', 'Most clients have two or three stories their mind replays: the not good enough story, the everyone leaves story, the I ruin things story. The page asks for the story in full, then a title for it, as if it were a film. From then on the move is simple: when the story starts, the client notes, here is the such-and-such story again. Have them say the title aloud in session. Watch for the client arguing with the story; the point is not to win the argument but to notice the rerun and keep doing what matters.', '[{"id": "f0", "type": "textarea", "label": "A story my mind tells about me, in full:"}, {"id": "f1", "type": "textarea", "label": "Its title, as if it were a film:"}, {"id": "f2", "type": "textarea", "label": "How often it plays, and what usually sets it off:"}, {"id": "f3", "type": "textarea", "label": "What I usually do when it plays:"}, {"id": "f4", "type": "textarea", "label": "What I would be doing if the story played and I let it run in the background:"}, {"id": "f5", "type": "textarea", "label": "This week: the times I noticed the story and named it:"}]'::jsonb, array['core ACT', 'defusion', 'self-as-context']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('thoughts-on-playing-cards-carry-page', 'Thoughts on Playing Cards Carry Page', 'act'::resource_kind, 'A hands-on ACT exercise where painful thoughts are written on cards the client carries in a pocket for a week.', 'Use it to show a client they can carry a thought with them and still go where they are going.', array['Adults', 'Teens']::text[], '15 minutes to set up, one week to carry', 'Write each sticky thought on an index card or a playing card in session. First ask the client to hold the cards in front of their face and describe how much of the room they can see, then to set them on their lap and look again. Then they carry the cards in a pocket for a week, taking them out when the thought shows up and putting them back. The page records what it was like to carry them to work, to dinner, to bed. The debrief is about the difference between a thought in the pocket and a thought in front of the eyes.', '[{"id": "f0", "type": "textarea", "label": "The thoughts I wrote on my cards:"}, {"id": "f1", "type": "textarea", "label": "What I could see with the cards in front of my face, and with them in my lap:"}, {"id": "f2", "type": "textarea", "label": "Places I carried the cards this week:"}, {"id": "f3", "type": "textarea", "label": "Times I took them out, and what I did after putting them back:"}, {"id": "f4", "type": "textarea", "label": "What is different about a thought in my pocket and a thought in front of my eyes:"}]'::jsonb, array['core ACT', 'defusion', 'metaphor']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('attention-flashlight-practice-page', 'Attention Flashlight Practice Page', 'act'::resource_kind, 'A contact-with-the-present practice that treats attention as a flashlight the client can aim, widen and narrow on purpose.', 'Use it to give a client a felt sense that attention is steerable, even when the mind pulls hard.', array['Adults', 'Teens']::text[], 'Ten minutes daily for two weeks', 'Describe attention as a flashlight: it points somewhere all the time, and the client can learn to aim it. In session, narrow the beam to one sound, widen it to the whole room, aim it at the feet, then at a thought, then back out the window. The page asks the client to practice a few aim-and-widen cycles daily and to notice where the beam goes when nobody is holding it. The skill is not keeping the beam still; it is noticing it has drifted and picking it back up. Pair it with a value the client wants to aim the beam at more often.', '[{"id": "f0", "type": "textarea", "label": "Where my flashlight usually points when nobody is holding it:"}, {"id": "f1", "type": "textarea", "label": "Today''s practice: narrow to one sound, widen to the room, aim at my feet. What I noticed:"}, {"id": "f2", "type": "textarea", "label": "A moment this week I caught the beam drifting and picked it up:"}, {"id": "f3", "type": "textarea", "label": "Something that matters to me that I want to aim the beam at more often:"}, {"id": "f4", "type": "textarea", "label": "What gets easier, and what does not, after two weeks:"}]'::jsonb, array['core ACT', 'mindfulness', 'attention']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('pressed-against-the-screen-metaphor-page', 'Pressed Against the Screen Metaphor Page', 'act'::resource_kind, 'A metaphor page comparing fusion to pressing one''s face to a screen of thoughts, and defusion to stepping back to see the room.', 'Use it to help a client feel the difference between being inside a thought and looking at it from a few feet back.', array['Adults', 'Teens']::text[], '20 minutes', 'Picture a screen showing the client''s thoughts. Pressed against it, nothing else exists: no room, no body, no exits. A few steps back, the screen is still on but the room is visible again, and the client can choose what to do in it. Walk the client through both positions with a recent painful thought, then ask what became visible in the room when they stepped back. The page is not about turning the screen off, which rarely works; it is about where the client stands. Return to it whenever a session gets stuck inside the content.', '[{"id": "f0", "type": "textarea", "label": "A thought I have been pressed up against this week:"}, {"id": "f1", "type": "textarea", "label": "Pressed against the screen: what I could and could not see:"}, {"id": "f2", "type": "textarea", "label": "A few steps back: what became visible in the room:"}, {"id": "f3", "type": "textarea", "label": "What I could do in the room with the screen still on:"}, {"id": "f4", "type": "textarea", "label": "What usually pulls me back up against the screen:"}, {"id": "f5", "type": "textarea", "label": "A cue I will use to take a step back this week:"}]'::jsonb, array['core ACT', 'defusion', 'metaphor']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('finding-potential-friends-sheet', 'Finding Potential Friends Sheet', 'dbt'::resource_kind, 'A DBT interpersonal effectiveness sheet for finding people who might become friends: proximity, similarity and conversation skills.', 'Use it to give a lonely client a concrete map of where new friends come from and what to do once they are nearby.', array['Adults', 'Teens']::text[], '30 minutes', 'This is the finding and getting people to like you module laid out plainly. Friends mostly come from proximity: the people seen repeatedly in the same place. The sheet asks where the client already is regularly, where they could be, who they see often but have not spoken to, and what shared interest or situation could open a conversation. Then it rehearses the small moves: a greeting, a question, a follow-up, an invitation. Watch for the client ruling out everyone before trying; the sheet is about volume of small attempts, not finding the perfect person.', '[{"id": "f0", "type": "textarea", "label": "Places I already go regularly where the same people show up:"}, {"id": "f1", "type": "textarea", "label": "A place I could start going regularly that fits something I like:"}, {"id": "f2", "type": "textarea", "label": "People I see often but have not really spoken to:"}, {"id": "f3", "type": "textarea", "label": "What we have in common that could open a conversation:"}, {"id": "f4", "type": "textarea", "label": "The small moves I will practice: a greeting, a question, a follow-up:"}, {"id": "f5", "type": "textarea", "label": "One invitation I could offer in the next two weeks:"}]'::jsonb, array['core DBT', 'interpersonal effectiveness', 'connection']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('extinction-burst-forecast-sheet', 'Extinction Burst Forecast Sheet', 'dbt'::resource_kind, 'A behavior change sheet that prepares a client for the temporary spike when a reinforced behavior stops being rewarded.', 'Use it to keep a client steady through the burst that comes after they stop feeding a pattern, their own or someone else''s.', array['Adults']::text[], '25 minutes', 'When a reinforced behavior stops getting its payoff, it usually gets louder before it fades. Clients who do not know this read the burst as proof the change failed and give the payoff back, which teaches the behavior to escalate. The sheet names the behavior, the reinforcer being withdrawn, what the burst will probably look like and how long the client will hold. It works for a child''s tantrums, a partner''s texting, or the client''s own habit. Plan the holding supports in advance and agree on what would be a real reason to stop, as opposed to the burst itself.', '[{"id": "f0", "type": "textarea", "label": "The behavior, and what has been rewarding it:"}, {"id": "f1", "type": "textarea", "label": "What I am going to stop doing that used to reward it:"}, {"id": "f2", "type": "textarea", "label": "What the burst will probably look like, and how I will know it is the burst:"}, {"id": "f3", "type": "textarea", "label": "How long I will hold, and who will help me hold:"}, {"id": "f4", "type": "textarea", "label": "A real reason I would stop, as opposed to the burst getting loud:"}, {"id": "f5", "type": "textarea", "label": "What I expect on the other side of the burst:"}]'::jsonb, array['core DBT', 'behavioral', 'habits']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('mindfulness-of-others-three-steps-sheet', 'Mindfulness of Others Three Steps Sheet', 'dbt'::resource_kind, 'A DBT interpersonal sheet for observing, describing and participating with another person instead of rehearsing one''s own reply.', 'Use it to pull a client out of their own head in conversation and into attention on the person in front of them.', array['Adults', 'Teens']::text[], '20 minutes to learn, one week to practice', 'Mindfulness of others applies the what skills to a conversation: observe the other person with curiosity, describe what you notice without judgment, participate fully in the exchange. The sheet asks the client to pick one low-stakes conversation a day and rate how much attention was on the other person versus on themselves. Clients who are anxious or who feel chronically unheard often discover they were only half in the room. Pair with validation skills once the observing is solid; this sheet is the foundation they need first.', '[{"id": "f0", "type": "textarea", "label": "A conversation this week I will practice in:"}, {"id": "f1", "type": "textarea", "label": "Observe: what I noticed about the other person''s face, voice and words:"}, {"id": "f2", "type": "textarea", "label": "Describe: what I could say about them without judging:"}, {"id": "f3", "type": "textarea", "label": "Participate: when I was fully in the exchange, and when I was in my own head:"}, {"id": "f4", "type": "textarea", "label": "How much of my attention was on them versus on me, out of ten:"}, {"id": "f5", "type": "textarea", "label": "What changed in the conversation when more attention went outward:"}]'::jsonb, array['core DBT', 'mindfulness', 'interpersonal effectiveness']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('building-structure-four-pillars-sheet', 'Building Structure Four Pillars Sheet', 'dbt'::resource_kind, 'A DBT sheet reviewing the structure in a client''s life across four pillars: work, love, time and place.', 'Use it to find which pillar of daily structure has gone thin and plan one repair there.', array['Adults']::text[], '30 minutes', 'Building structure asks whether a client''s life has enough shape to hold them. Work is anything that gives purpose and routine, paid or not; love is people and belonging; time is a daily rhythm of sleep, meals and activity; place is a physical setting that is safe and reasonably ordered. The sheet rates each pillar and asks what is missing. Most clients find one pillar carrying the others. Plan one repair in the weakest pillar for the week, and keep it modest: a standing walk, a weekly call, a cleared corner. Revisit monthly.', '[{"id": "f0", "type": "textarea", "label": "Work: what gives my days purpose and routine right now, paid or not:"}, {"id": "f1", "type": "textarea", "label": "Love: the people and places where I belong:"}, {"id": "f2", "type": "textarea", "label": "Time: what my sleep, meals and daily rhythm actually look like:"}, {"id": "f3", "type": "textarea", "label": "Place: how my physical space supports or drains me:"}, {"id": "f4", "type": "textarea", "label": "The pillar that feels thinnest, and why:"}, {"id": "f5", "type": "textarea", "label": "One repair I will make there this week:"}]'::jsonb, array['core DBT', 'routines', 'emotion regulation']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('ending-a-destructive-relationship-decision-sheet', 'Ending a Destructive Relationship Decision Sheet', 'dbt'::resource_kind, 'A DBT interpersonal sheet for deciding, in wise mind, whether to end a relationship that keeps doing harm, and how.', 'Use it to slow a client''s decision about a harmful relationship down into wise mind, with the practical steps mapped.', array['Adults']::text[], 'Full session', 'The skill starts with a distinction: a relationship that is hard versus one that is destructive to the client''s wellbeing or values. The sheet asks the client to describe the pattern plainly, check whether repair has been genuinely tried, and run a pros and cons in wise mind rather than at the height or the low of the cycle. If the decision is to end it, the sheet moves to the how: the cope ahead, the safety plan where there is any risk, the people who will help. Complete the safety portion in session, and name 988 (call or text) and local resources on the plan if risk of any kind is present.', '[{"id": "f0", "type": "textarea", "label": "The pattern in this relationship, described in plain facts:"}, {"id": "f1", "type": "textarea", "label": "Ways repair has actually been tried, and what happened:"}, {"id": "f2", "type": "textarea", "label": "Pros and cons of staying, written in wise mind rather than at the high or low of the cycle:"}, {"id": "f3", "type": "textarea", "label": "Pros and cons of ending it:"}, {"id": "f4", "type": "textarea", "label": "If I end it: how, when and with whom I will talk it through first:"}, {"id": "f5", "type": "textarea", "label": "My safety plan, including who I call and 988 (call or text) if I am ever in danger or in crisis:"}]'::jsonb, array['core DBT', 'interpersonal effectiveness', 'boundaries', 'safety']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('two-ovals-compromise-sheet-for-partners', 'Two Ovals Compromise Sheet for Partners', 'couples'::resource_kind, 'A Gottman-style sheet where each partner draws an inner oval of core needs and an outer oval of flexible areas on one issue.', 'Use it to help a couple find where a compromise can live without either partner giving up what they cannot give up.', array['Couples']::text[], '45 minutes', 'Each partner takes one stuck issue and draws two ovals: the inner one holds the parts of their position they cannot yield without losing something essential; the outer one holds everything flexible. Partners read each other''s ovals aloud and ask questions before any bargaining. The compromise is built only from the outer ovals. The usual surprise is that the inner ovals are smaller than either expected and rarely collide. Watch for a partner stuffing the inner oval to avoid moving; ask what each item protects.', '[{"id": "f0", "type": "textarea", "label": "Partner A: the issue, and my inner oval, the parts I cannot give up and what each protects:"}, {"id": "f1", "type": "textarea", "label": "Partner A: my outer oval, the parts I can be flexible on:"}, {"id": "f2", "type": "textarea", "label": "Partner B: the issue, and my inner oval, the parts I cannot give up and what each protects:"}, {"id": "f3", "type": "textarea", "label": "Partner B: my outer oval, the parts I can be flexible on:"}, {"id": "f4", "type": "textarea", "label": "Where our outer ovals overlap:"}, {"id": "f5", "type": "textarea", "label": "The compromise we will try for two weeks, built only from the outer ovals:"}]'::jsonb, array['couples', 'Gottman', 'conflict']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('attune-steps-card-for-partners', 'ATTUNE Steps Card for Partners', 'couples'::resource_kind, 'A card walking a listening partner through awareness, turning toward, tolerance, understanding, nondefensive response and empathy.', 'Use it to give the listening partner a sequence to hold when the other brings something hard.', array['Couples']::text[], '30 minutes to learn, used in each hard conversation', 'ATTUNE is a Gottman sequence for the listener: awareness of the partner''s feeling, turning toward it, tolerance that two views can both be valid, understanding before problem solving, nondefensive responding, and empathy. Teach it with one real, mid-sized topic. The speaker talks for three minutes; the listener holds the card and goes through the letters, then they swap. The hardest step is almost always tolerance, when the listener hears something they disagree with and wants to correct it. Name that moment when you see it.', '[{"id": "f0", "type": "textarea", "label": "Partner A listening: where I noticed my partner''s feeling, and what I did to turn toward it:"}, {"id": "f1", "type": "textarea", "label": "Partner A: the moment I wanted to correct rather than tolerate, and what I did instead:"}, {"id": "f2", "type": "textarea", "label": "Partner A: what I understood before I tried to fix anything:"}, {"id": "f3", "type": "textarea", "label": "Partner B listening: where I noticed my partner''s feeling, and what I did to turn toward it:"}, {"id": "f4", "type": "textarea", "label": "Partner B: the moment I wanted to correct rather than tolerate, and what I did instead:"}, {"id": "f5", "type": "textarea", "label": "Partner B: what I understood before I tried to fix anything:"}, {"id": "f6", "type": "textarea", "label": "The letter each of us finds hardest, and how we will practice it this week:"}]'::jsonb, array['couples', 'Gottman', 'listening']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('gridlock-versus-solvable-problem-sort-for-partners', 'Gridlock Versus Solvable Problem Sort for Partners', 'couples'::resource_kind, 'A sorting sheet that separates a couple''s solvable problems from their perpetual ones, so each gets the right kind of conversation.', 'Use it to stop a couple from trying to solve a perpetual difference and from endlessly discussing a solvable one.', array['Couples']::text[], '40 minutes', 'Couples waste effort treating every difference the same way. The sheet lists their recurring issues and sorts each: solvable (a situation with a fix once they agree) or perpetual (a difference in personality or need that will be with them for years). Solvable problems get a compromise conversation; perpetual ones get a dialogue about what each position means to each partner and how to live alongside the difference. The relief of calling something perpetual is often visible in the room. Watch for one partner sorting everything as solvable because solving feels like winning.', '[{"id": "f0", "type": "textarea", "label": "Partner A: our recurring issues, as I would list them:"}, {"id": "f1", "type": "textarea", "label": "Partner B: our recurring issues, as I would list them:"}, {"id": "f2", "type": "textarea", "label": "Together: which of these are solvable with a plan we both accept:"}, {"id": "f3", "type": "textarea", "label": "Together: which are perpetual differences we will be living with:"}, {"id": "f4", "type": "textarea", "label": "One solvable issue we will build a plan for first:"}, {"id": "f5", "type": "textarea", "label": "One perpetual issue we will talk about differently, starting with what it means to each of us:"}]'::jsonb, array['couples', 'Gottman', 'conflict', 'problem solving']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('magic-five-hours-a-week-planner-for-partners', 'Magic Five Hours a Week Planner for Partners', 'couples'::resource_kind, 'A weekly planner that places five hours of small connection moments: partings, reunions, appreciation, affection and a date.', 'Use it to give a busy couple a realistic weekly shape for connection that adds up to five hours.', array['Couples']::text[], '30 minutes to plan, one week to run', 'The five hours come from small daily pieces: learning one thing about each other''s day before parting, a six-second kiss and a real conversation at reunion, a daily appreciation, daily physical affection, and a weekly date of a couple of hours. The planner lays these on the week with times attached, since good intentions without times rarely happen. Have the couple pick times that already exist in their routine rather than new ones. Review the week together: which pieces happened, which did not, and what got in the way.', '[{"id": "f0", "type": "textarea", "label": "Partner A: the piece of this I most want, and the piece I expect to be hardest:"}, {"id": "f1", "type": "textarea", "label": "Partner B: the piece of this I most want, and the piece I expect to be hardest:"}, {"id": "f2", "type": "textarea", "label": "Partings: what we will ask each other before leaving each morning:"}, {"id": "f3", "type": "textarea", "label": "Reunions: how we will greet each other at the end of the day:"}, {"id": "f4", "type": "textarea", "label": "Appreciation and affection: when in the day each will happen:"}, {"id": "f5", "type": "textarea", "label": "Our two-hour date this week: when, where and who is covering anything that needs covering:"}]'::jsonb, array['couples', 'Gottman', 'connection']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('caring-behaviors-request-list-for-partners', 'Caring Behaviors Request List for Partners', 'couples'::resource_kind, 'An Imago-style list where each partner writes specific small behaviors that make them feel cared for and the other picks from it.', 'Use it to replace guessing with a menu, so each partner knows exactly what lands as care for the other.', array['Couples']::text[], '40 minutes', 'Each partner writes a list of small, positive, specific, doable behaviors that make them feel loved: a coffee brought to the desk, a text at lunch, a hand on the back passing in the kitchen. Not complaints in disguise, not things the other has refused. Partners swap lists and, without discussion, each chooses two or three to do in the coming week as gifts, no scorekeeping. Debrief on how it felt to receive and to give. The lists often reveal how far apart the two ideas of care have been.', '[{"id": "f0", "type": "textarea", "label": "Partner A: small, specific things that make me feel cared for:"}, {"id": "f1", "type": "textarea", "label": "Partner B: small, specific things that make me feel cared for:"}, {"id": "f2", "type": "textarea", "label": "Partner A: the items from my partner''s list I will gift this week:"}, {"id": "f3", "type": "textarea", "label": "Partner B: the items from my partner''s list I will gift this week:"}, {"id": "f4", "type": "textarea", "label": "What it was like to receive something from my own list:"}, {"id": "f5", "type": "textarea", "label": "What surprised each of us about the other''s list:"}]'::jsonb, array['couples', 'connection', 'appreciation']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('birthday-candle-breathing-play', 'Birthday Candle Breathing Play', 'kids'::resource_kind, 'A breathing game where a child blows out pretend birthday candles one at a time, slowing the breath with each one.', 'Use it to teach a young child a long slow exhale through a game they already know how to play.', array['Children']::text[], 'Five minutes, repeated as often as wanted', 'Hold up five fingers as candles. The child takes a breath in through the nose, then blows out one candle with a long slow breath; the finger folds down. Five candles, five breaths. For a child who blows hard and fast, make the candles stubborn: they only go out with a slow, steady breath. The parent plays it too, with their own hand of candles, so the child sees a grown-up breathing slowly. Teach it when the child is calm, and tell the parent to use it before the child is at full volume, not after.', '[{"id": "f0", "type": "textarea", "label": "How many candles I blew out today, and how slow my breath was:"}, {"id": "f1", "type": "textarea", "label": "What happened when I blew too fast and the candle stayed lit:"}, {"id": "f2", "type": "textarea", "label": "Who played candles with me:"}, {"id": "f3", "type": "textarea", "label": "A time I might use my candles when I feel wobbly:"}, {"id": "f4", "type": "textarea", "label": "Parent: when we practiced, and when I tried it before a hard moment:"}]'::jsonb, array['children', 'breathing', 'play']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('starfish-hand-breathing-trace-craft', 'Starfish Hand Breathing Trace Craft', 'kids'::resource_kind, 'A child traces their own hand into a starfish, decorates it, and breathes in up each arm and out down the next.', 'Use it to give a child a breathing tool that is always with them, since the starfish is their own hand.', array['Children']::text[], '20 minutes to make, one minute to use', 'Trace the child''s hand on card, turn it into a starfish with eyes and spots, and cut it out. To breathe, the finger of the other hand starts at the wrist, slides up the thumb breathing in, down the other side breathing out, and so on across all five arms. Once the card version is familiar, show the child that their real hand works the same way anywhere. The parent traces their own hand alongside and practices at bedtime. Children who dislike sitting still for breathing often accept this because the finger has a job.', '[{"id": "f0", "type": "textarea", "label": "The colors and spots on my starfish:"}, {"id": "f1", "type": "textarea", "label": "How it felt to trace up and down all five arms:"}, {"id": "f2", "type": "textarea", "label": "Where my starfish card lives:"}, {"id": "f3", "type": "textarea", "label": "A time I used my real hand as a starfish when I did not have the card:"}, {"id": "f4", "type": "textarea", "label": "Parent: when we practiced together this week:"}]'::jsonb, array['children', 'breathing', 'craft']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('rain-stick-calm-sounds-craft', 'Rain Stick Calm Sounds Craft', 'kids'::resource_kind, 'A child builds a rain stick from a cardboard tube, foil and rice, then uses the sound to settle and to time a slow breath.', 'Use it to give a child a calming sound they made themselves and a reason to slow down and listen.', array['Children']::text[], '30 minutes to make, used in calm-down moments', 'A paper towel tube, a coil of crumpled foil pushed inside, a handful of rice or dried beans, and taped ends make a rain stick. The child decorates the outside. To use it, the child tips it slowly and listens to the whole trickle, breathing out as long as the sound lasts. Then tips it back. The parent helps with the build and sits with the child to listen at calm times so the sound becomes familiar. Tell the parent it is a settling tool, not a reward or a punishment, and to keep it on a reachable shelf.', '[{"id": "f0", "type": "textarea", "label": "What I put inside my rain stick and what it sounds like:"}, {"id": "f1", "type": "textarea", "label": "How long the rain lasts when I tip it slowly:"}, {"id": "f2", "type": "textarea", "label": "How my body feels after listening to the whole trickle:"}, {"id": "f3", "type": "textarea", "label": "Where my rain stick lives at home:"}, {"id": "f4", "type": "textarea", "label": "Parent: a calm time we listened together, and a time it helped during a wobble:"}]'::jsonb, array['children', 'craft', 'calming']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('building-blocks-safe-place-build-and-play', 'Building Blocks Safe Place Build and Play', 'kids'::resource_kind, 'A child builds a safe place out of blocks and plays out who lives there, who is allowed in and what happens when a worry arrives.', 'Use it to let a child show you what safety looks like to them through building and play rather than words.', array['Children']::text[], '30 minutes', 'Any building blocks work. Ask the child to build a place where someone small could feel completely safe, then furnish it with figures. Ask who lives there, who is allowed in, what the rules are, and what happens when a worry comes knocking. Follow the child''s play; do not steer it. The parent builds alongside and asks the same open questions, then takes a photo of the build so it can be revisited. What the child includes and excludes is useful to you; keep your notes for yourself and let the child keep the story.', '[{"id": "f0", "type": "textarea", "label": "What my safe place looks like and what is inside it:"}, {"id": "f1", "type": "textarea", "label": "Who lives there and who is allowed to visit:"}, {"id": "f2", "type": "textarea", "label": "The rules of my safe place:"}, {"id": "f3", "type": "textarea", "label": "What happens when a worry knocks on the door:"}, {"id": "f4", "type": "textarea", "label": "Parent: what I noticed while we built, and the photo we took to remember it:"}]'::jsonb, array['children', 'play', 'safety']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('emoji-faces-feelings-fan-craft', 'Emoji Faces Feelings Fan Craft', 'kids'::resource_kind, 'A child draws feeling faces on paper circles, fastens them into a fan, and flips to the face that matches how they feel.', 'Use it to give a child who cannot find the word a way to show the feeling with a face they drew.', array['Children']::text[], '25 minutes to make, used daily', 'Cut six to eight circles, and have the child draw a different feeling face on each, naming it as they go. Punch a hole in each and fasten them with a brad or a loop of string so they fan out. At check-in times, the child flips to the face that fits and the parent asks about it rather than correcting it. Keep the set honest: include bored, grumpy and worried, not just happy and sad. The parent keeps a fan too and shows their own face at dinner, which models that grown-ups have feelings they can name.', '[{"id": "f0", "type": "textarea", "label": "The faces on my fan and their names:"}, {"id": "f1", "type": "textarea", "label": "The face I showed today and why:"}, {"id": "f2", "type": "textarea", "label": "A feeling I wanted a face for but did not have yet:"}, {"id": "f3", "type": "textarea", "label": "Parent: the face I showed at dinner tonight:"}, {"id": "f4", "type": "textarea", "label": "Parent: a time the fan helped us talk about something hard:"}]'::jsonb, array['children', 'emotion identification', 'craft']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('hula-hoop-pass-teamwork-circle-game', 'Hula Hoop Pass Teamwork Circle Game', 'game'::resource_kind, 'A circle game where a hoop travels around a ring of linked hands without anyone letting go, timed and then debriefed.', 'Use it to give a group a shared, slightly silly task that shows how they help, hurry and get stuck together.', array['Groups', 'Teens', 'Children']::text[], '20 minutes', 'Rules: the group stands in a circle holding hands. A hula hoop hangs on one pair of joined hands. The hoop must travel all the way around the circle, each person stepping through it, without any hands letting go. Time the first lap, then let the group talk for one minute and try to beat it. Three laps. Debrief: who gave instructions, who got stuck and how the group reacted, what the group changed between laps. Link it to how the group handles a stuck member in real life.', '[{"id": "f0", "type": "textarea", "label": "Our three lap times:"}, {"id": "f1", "type": "textarea", "label": "What we changed between laps:"}, {"id": "f2", "type": "textarea", "label": "A moment I was stuck in the hoop, and what the group did:"}, {"id": "f3", "type": "textarea", "label": "Who gave the most instructions, and how that went:"}, {"id": "f4", "type": "textarea", "label": "One thing from the game that is true about how we work together off the field:"}]'::jsonb, array['game', 'group', 'communication']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('balloon-keep-up-cooperation-game', 'Balloon Keep Up Cooperation Game', 'game'::resource_kind, 'A group keeps one or more balloons in the air with rules that change each round, then talks about what helped and what did not.', 'Use it to get a group moving, laughing and noticing how they share a task under small pressures.', array['Groups', 'Children', 'Teens']::text[], '20 minutes', 'Rules: one balloon, no one may hit it twice in a row, count the hits aloud. Round two: add a second balloon. Round three: no talking. Round four: only non-dominant hands. Reset the count to zero when a balloon touches the floor. Debrief on which round was hardest and why, what the group did when the count reset, and who tended to take over or hang back. With children, keep the debrief to two questions. The game also works as a quick body-based reset in the middle of a heavy session.', '[{"id": "f0", "type": "textarea", "label": "Our best count in each round:"}, {"id": "f1", "type": "textarea", "label": "The round that was hardest for me, and why:"}, {"id": "f2", "type": "textarea", "label": "What happened in the group when a balloon hit the floor:"}, {"id": "f3", "type": "textarea", "label": "Whether I tended to take over or hang back:"}, {"id": "f4", "type": "textarea", "label": "One thing I want to do differently next time we have a group task:"}]'::jsonb, array['game', 'group', 'regulation']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('fact-or-opinion-speed-sort-game', 'Fact or Opinion Speed Sort Game', 'game'::resource_kind, 'A fast card game sorting statements into facts and opinions, with a final round using the players'' own thoughts about themselves.', 'Use it to build the muscle of telling a fact from an opinion before pointing it at a client''s self-talk.', array['Teens', 'Adults', 'Groups']::text[], '25 minutes', 'Rules: prepare thirty cards with statements, two-thirds plainly fact or opinion (the sky is blue; pizza is the best food) and a third that sound factual but are opinions (nobody likes a complainer). Players race to sort them into two piles; a wrong placement costs a point and is discussed. In the final round, each player writes three things they tell themselves on blank cards and the group sorts those. Debrief on which self-statements landed as opinions and what it would mean to hold them that way. Keep the tone light; the final round carries itself.', '[{"id": "f0", "type": "textarea", "label": "Cards I got wrong in the first rounds, and why they fooled me:"}, {"id": "f1", "type": "textarea", "label": "The three things I tell myself that I wrote on cards:"}, {"id": "f2", "type": "textarea", "label": "Which of mine the group sorted as opinion:"}, {"id": "f3", "type": "textarea", "label": "How it felt to see my own thought in the opinion pile:"}, {"id": "f4", "type": "textarea", "label": "One self-statement I will treat as an opinion this week:"}]'::jsonb, array['game', 'thinking traps', 'self-talk']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('silent-line-up-by-birthday-game', 'Silent Line Up by Birthday Game', 'game'::resource_kind, 'A group lines up in birthday order without speaking, then debriefs how they communicated and who took charge.', 'Use it to show a group how much they can communicate without words, and how it feels to be misread.', array['Groups', 'Teens', 'Adults']::text[], '15 minutes', 'Rules: no talking, no mouthing words, no writing. The group must line up in order of birthday, January at one end and December at the other, then check by saying birthdays down the line. Time it. Run it again ordered by something less obvious, such as how far each person traveled today. Debrief: what gestures worked, who organized and how the group let them, what it was like to be misunderstood with no way to explain. Groups with a member who struggles to be heard often find this opens that conversation safely.', '[{"id": "f0", "type": "textarea", "label": "How we communicated without words, and what worked best:"}, {"id": "f1", "type": "textarea", "label": "Who took charge, and how the group responded:"}, {"id": "f2", "type": "textarea", "label": "A moment I was misread and could not explain:"}, {"id": "f3", "type": "textarea", "label": "How close we got, and what we would do differently:"}, {"id": "f4", "type": "textarea", "label": "Where in my life I communicate without words, and how that goes:"}]'::jsonb, array['game', 'group', 'communication']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('marshmallow-and-spaghetti-tower-challenge-game', 'Marshmallow and Spaghetti Tower Challenge Game', 'game'::resource_kind, 'Small teams build the tallest free-standing tower from dry spaghetti, tape and a marshmallow on top, under a timer.', 'Use it to watch a group plan, fail, adapt and handle a collapse together in fifteen minutes.', array['Groups', 'Teens', 'Adults']::text[], '30 minutes', 'Rules: each team gets twenty sticks of dry spaghetti, a yard of tape, a yard of string and one marshmallow. In fifteen minutes build the tallest free-standing structure with the marshmallow on top. Measure only towers standing when the timer ends. Debrief: when did the team put the marshmallow on, and what happened? Who planned and who built? What did the team do after a collapse? Towers that fall at the last second are the best teaching material; stay with the team''s reaction to it rather than consoling too fast.', '[{"id": "f0", "type": "textarea", "label": "Our tower height, and whether it was standing at the end:"}, {"id": "f1", "type": "textarea", "label": "When we first tested the marshmallow on top, and what happened:"}, {"id": "f2", "type": "textarea", "label": "What my role was: planner, builder, watcher or something else:"}, {"id": "f3", "type": "textarea", "label": "How our team reacted when something collapsed:"}, {"id": "f4", "type": "textarea", "label": "One thing about how I handle a collapse that showed up in the game:"}]'::jsonb, array['game', 'group', 'problem solving']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('room-scanning-habit-pause-and-redirect-sheet', 'Room Scanning Habit Pause and Redirect Sheet', 'worksheet'::resource_kind, 'A sheet for the habit of scanning every room for exits and threats, logging when it happens and practicing one deliberate redirect.', 'Use it to help a client notice the scanning habit as it happens and choose where attention goes next.', array['Adults', 'Teens']::text[], 'Ten minutes daily for two weeks', 'Scanning is often automatic and exhausting, and clients rarely count how much of a social evening goes to it. The sheet has the client log a few scanning moments a day: where, what the scan was looking for, and how long before they could attend to anything else. Then one redirect per day: after a single deliberate scan, naming three neutral things in the room, or returning to the conversation. The point is not to stop scanning, which the body will not agree to yet, but to add a chosen next step. Keep the pace slow and the tone respectful of what the scanning once did.', '[{"id": "f0", "type": "textarea", "label": "A moment today I noticed myself scanning, and what I was looking for:"}, {"id": "f1", "type": "textarea", "label": "How long it took before I could pay attention to anything else:"}, {"id": "f2", "type": "textarea", "label": "My one redirect today after a deliberate scan:"}, {"id": "f3", "type": "textarea", "label": "What the scanning habit has protected me from, in its own time:"}, {"id": "f4", "type": "textarea", "label": "After two weeks: what has shifted, and what has not:"}]'::jsonb, array['PTSD and trauma', 'grounding', 'attention']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('the-whole-world-is-dangerous-overgeneralization-sheet', 'The Whole World Is Dangerous Overgeneralization Sheet', 'cbt'::resource_kind, 'A CBT sheet that takes a global belief about danger after trauma and tests it against specific places, people and times.', 'Use it to help a client separate the place where harm happened from the whole world the belief has spread to.', array['Adults', 'Teens']::text[], '30 minutes', 'After trauma the belief that nowhere is safe is understandable and costly. The sheet writes the belief in the client''s words, then lists specific settings from their week and rates each for how dangerous the belief says it is and how dangerous the evidence of their actual experience says it is. The gaps are the work. Do not argue the belief down; let the client''s own ratings do it, and respect any setting that genuinely is unsafe. Finish with one setting where the two ratings differ most and a small step there. Keep this to settings, never to retelling the event.', '[{"id": "f0", "type": "textarea", "label": "The belief about danger, in my own words:"}, {"id": "f1", "type": "textarea", "label": "Settings from my week, each rated for how dangerous the belief says it is (0 to 100):"}, {"id": "f2", "type": "textarea", "label": "The same settings rated by what has actually happened to me there:"}, {"id": "f3", "type": "textarea", "label": "The setting where the two numbers differ most:"}, {"id": "f4", "type": "textarea", "label": "A small step in that setting this week, with a way out planned:"}, {"id": "f5", "type": "textarea", "label": "What I would want to believe about danger a year from now:"}]'::jsonb, array['PTSD and trauma', 'core CBT', 'thinking traps']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('smoke-alarm-mind-metaphor-page', 'Smoke Alarm Mind Metaphor Page', 'act'::resource_kind, 'An ACT page that treats trauma reminders as a smoke alarm set too sensitive, going off for toast as well as fire.', 'Use it to help a client relate to their alarm reactions as a sensitive device rather than a true reading of danger.', array['Adults', 'Teens']::text[], '20 minutes', 'A smoke alarm that has been through a real fire often gets set more sensitive, and then it goes off for toast. The page asks the client to list some recent alarms and sort them, in hindsight only, into toast and fire. It never asks them to ignore the alarm; it asks what they want to do while it is sounding. Clients find it easier to thank the alarm for trying than to fight it. Pair with a grounding step for while the alarm rings. Steer clear of the original fire; this page is about the device, not the event.', '[{"id": "f0", "type": "textarea", "label": "Recent times my alarm went off, and what set it off:"}, {"id": "f1", "type": "textarea", "label": "Looking back, which ones were toast and which were fire:"}, {"id": "f2", "type": "textarea", "label": "What my alarm has been trying to do for me:"}, {"id": "f3", "type": "textarea", "label": "What I want to do while the alarm is sounding, instead of running the house:"}, {"id": "f4", "type": "textarea", "label": "One sentence I can say to the alarm when it goes off for toast:"}]'::jsonb, array['PTSD and trauma', 'core ACT', 'metaphor']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('stop-skill-at-a-trauma-reminder-card', 'STOP Skill at a Trauma Reminder Card', 'dbt'::resource_kind, 'A pocket card that runs the DBT STOP skill at the moment a reminder hits: stop, take a step back, observe, proceed mindfully.', 'Use it to give a client four moves for the first thirty seconds after a reminder, before the body takes over.', array['Adults', 'Teens']::text[], 'Ten minutes to learn, used at the moment', 'STOP is short enough to run while the heart is pounding. Stop: freeze the body, do nothing yet. Take a step back: literally one step, or one breath. Observe: name what is here now, the date, the room, three objects. Proceed mindfully: choose the next small action. Rehearse it in session with a mild reminder the client agrees to, never a severe one, until the four words come without the card. The card stays in a pocket or on a lock screen. Debrief each real use for which letter was hardest.', '[{"id": "f0", "type": "textarea", "label": "The reminders I most want this card for:"}, {"id": "f1", "type": "textarea", "label": "Stop: what I will do with my body in the first second:"}, {"id": "f2", "type": "textarea", "label": "Take a step back: my one step or one breath:"}, {"id": "f3", "type": "textarea", "label": "Observe: the three things I will name about where I am right now:"}, {"id": "f4", "type": "textarea", "label": "Proceed: the next small action I will choose:"}, {"id": "f5", "type": "textarea", "label": "This week''s uses, and which letter was hardest each time:"}]'::jsonb, array['PTSD and trauma', 'core DBT', 'grounding']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('brave-and-safe-superhero-pose-play', 'Brave and Safe Superhero Pose Play', 'kids'::resource_kind, 'A child invents a superhero pose that means I am safe right now and practices it with a grown-up until it is automatic.', 'Use it to give a child a body-based way back to the present, with a parent who knows the pose and strikes it too.', array['Children']::text[], '15 minutes, repeated daily', 'Ask the child to invent a pose for a hero whose power is feeling safe: feet planted, maybe hands on hips, maybe a cape swish. Name the hero together. Practice striking the pose and saying the hero''s line, something like I am here and I am safe. The parent learns the pose and strikes it alongside, at calm times first, then as a cue when the child seems far away. Keep it playful and keep it away from any talk of what happened. If a child discloses abuse or harm during play, follow your mandated reporting duties and your agency''s steps.', '[{"id": "f0", "type": "textarea", "label": "My hero''s name and what the pose looks like:"}, {"id": "f1", "type": "textarea", "label": "My hero''s line:"}, {"id": "f2", "type": "textarea", "label": "Where I feel the pose in my body when I strike it:"}, {"id": "f3", "type": "textarea", "label": "A time this week I used my pose, and who did it with me:"}, {"id": "f4", "type": "textarea", "label": "Parent: when we practiced at calm times, and a time I used it as a cue:"}]'::jsonb, array['PTSD and trauma', 'children', 'grounding']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('waiting-for-test-results-holding-plan-sheet', 'Waiting for Test Results Holding Plan Sheet', 'worksheet'::resource_kind, 'A plan for the days between a test and its result, with what to do with checking urges, the hours and the people around.', 'Use it to help a client get through a results wait without the wait eating every hour of the week.', array['Adults', 'Teens']::text[], '20 minutes', 'Results waits, medical or academic or legal, turn a week into one long held breath. The sheet asks when the result is actually due, how the client will receive it, and what checking the portal or inbox more often will and will not change. Then it fills the days: anchor activities, one person who knows about the wait, a plan for the moment the result arrives either way. Watch for the client treating the plan as a way to stop feeling anxious; its job is to keep the week from collapsing into the wait, not to remove the worry.', '[{"id": "f0", "type": "textarea", "label": "What I am waiting for, when it is actually due and how I will get it:"}, {"id": "f1", "type": "textarea", "label": "How often I am checking now, and what checking changes:"}, {"id": "f2", "type": "textarea", "label": "My anchor activities for each waiting day:"}, {"id": "f3", "type": "textarea", "label": "The one person who knows I am waiting and what I want from them:"}, {"id": "f4", "type": "textarea", "label": "My plan for the first hour after the result, if it is good news and if it is not:"}]'::jsonb, array['anxiety', 'uncertainty', 'planning']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('anxious-feeling-means-danger-belief-check-sheet', 'Anxious Feeling Means Danger Belief Check Sheet', 'cbt'::resource_kind, 'A CBT sheet testing the belief that feeling anxious is proof something is wrong, using the client''s own week of alarms.', 'Use it to loosen the link a client has made between the feeling of anxiety and the presence of a real problem.', array['Adults', 'Teens']::text[], '25 minutes', 'Emotional reasoning about anxiety is circular: I feel anxious, so something must be wrong, so I feel more anxious. The sheet asks the client to list the past week''s anxious moments and, for each, what actually turned out to be wrong. Then it asks the reverse: times something was wrong and they did not feel anxious at all. The two lists make the point without a lecture. Finish with a replacement sentence the client finds believable, such as anxiety means my body is alert, not that something is wrong.', '[{"id": "f0", "type": "textarea", "label": "Times this week I felt anxious, and what my mind said was wrong:"}, {"id": "f1", "type": "textarea", "label": "For each, what actually turned out to be wrong:"}, {"id": "f2", "type": "textarea", "label": "Times something really was wrong and I did not feel anxious beforehand:"}, {"id": "f3", "type": "textarea", "label": "What these two lists say about anxiety as a danger signal:"}, {"id": "f4", "type": "textarea", "label": "A sentence about what anxiety means that I can actually believe:"}]'::jsonb, array['anxiety', 'core CBT', 'thinking traps']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('knot-in-the-stomach-making-room-page', 'Knot in the Stomach Making Room Page', 'act'::resource_kind, 'An ACT expansion page that works directly with the knot in the stomach, breathing around it and letting it have its space.', 'Use it to teach a client to make room for the physical knot of anxiety instead of trying to untie it.', array['Adults', 'Teens']::text[], '15 minutes, then daily', 'Ask the client to find the knot, describe its edges, size, temperature and texture, and then to breathe around it as if making a little space for it to sit in. Not to relax it, not to breathe it away; to let it be there with room. Many notice the knot shifts when it stops being fought, and some notice it does not, which is also fine. The page tracks daily practice and what the client did with the day while the knot was present. Keep the language of allowing rather than fixing, and catch the client turning it into a new way to get rid of the knot.', '[{"id": "f0", "type": "textarea", "label": "Where the knot sits, and its size, edges, temperature and texture:"}, {"id": "f1", "type": "textarea", "label": "What happened when I breathed around it and gave it room:"}, {"id": "f2", "type": "textarea", "label": "What I usually do to try to untie it, and how that goes:"}, {"id": "f3", "type": "textarea", "label": "What I did with my day today while the knot was present:"}, {"id": "f4", "type": "textarea", "label": "After a week: what I notice about the knot when I stop fighting it:"}]'::jsonb, array['anxiety', 'core ACT', 'acceptance']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('self-soothe-with-sight-anxious-evening-menu-card', 'Self-Soothe With Sight Anxious Evening Menu Card', 'dbt'::resource_kind, 'A DBT self-soothe card built on the sense of sight alone: specific things to look at that settle an anxious evening.', 'Use it to give a client a visual self-soothing menu for the evening hours when worry climbs.', array['Adults', 'Teens']::text[], '15 minutes to build, used nightly', 'Self-soothe through sight is the sense most clients skip, and the one most available at night. The card lists five to eight things the client can look at that settle them: a candle flame, a photo, the sky from a window, a slow video of waves, a plant, a sleeping pet. Have them build it from memory of what has actually calmed them before, not from what sounds nice. The evening practice is one item for five minutes, phone out of reach, attention on what is seen. Watch for the client reaching for a screen as the visual, and ask what it does to their body compared with the others.', '[{"id": "f0", "type": "textarea", "label": "Things to look at that have actually settled me before:"}, {"id": "f1", "type": "textarea", "label": "My five to eight sight items, and where each is in my home:"}, {"id": "f2", "type": "textarea", "label": "Tonight''s item, and what I noticed in my body after five minutes:"}, {"id": "f3", "type": "textarea", "label": "What my eyes wanted to drift to instead, and what that does to me:"}, {"id": "f4", "type": "textarea", "label": "The items that worked best this week:"}]'::jsonb, array['anxiety', 'core DBT', 'self-soothing']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('worry-hot-potato-pass-game', 'Worry Hot Potato Pass Game', 'game'::resource_kind, 'A circle game where a worry travels like a hot potato and each player who catches it must add one grounded reply before passing.', 'Use it to let a group practice quick, kind replies to worry thoughts while moving and laughing.', array['Groups', 'Teens', 'Children']::text[], '20 minutes', 'Rules: one player states a worry out loud and tosses a soft ball. Whoever catches it has five seconds to say one reply that is true and kind, not a dismissal (not it will be fine), then names a new worry and tosses on. Replies that are dismissive or that argue cost a point and the group offers a better one. Play until each player has caught at least three. Debrief: which replies felt real, what the difference was between kind and dismissive, and which reply each player will keep for their own worry this week.', '[{"id": "f0", "type": "textarea", "label": "The worries I tossed into the game:"}, {"id": "f1", "type": "textarea", "label": "The best reply I caught from someone else:"}, {"id": "f2", "type": "textarea", "label": "A reply I gave that the group said was dismissive, and how we fixed it:"}, {"id": "f3", "type": "textarea", "label": "The difference, in my words, between a kind reply and a brush-off:"}, {"id": "f4", "type": "textarea", "label": "The reply I will keep for my own worry this week:"}]'::jsonb, array['anxiety', 'game', 'group']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('daylight-minutes-and-mood-log', 'Daylight Minutes and Mood Log', 'worksheet'::resource_kind, 'A simple week log of minutes spent in daylight, outdoors or at a window, beside a mood rating for the day.', 'Use it to let a client see their own pattern between light exposure and mood, and plan a few more minutes if it shows.', array['Adults', 'Teens']::text[], 'Two minutes daily for two weeks', 'Clients in a low stretch often go days without daylight and do not notice. The log asks for a rough count of daylight minutes, where they got them, and a mood rating at the end of the day. After two weeks the client looks for their own pattern rather than being told one. If a pattern shows, the plan is modest: a morning window, a walk to the mailbox, coffee on the step. Keep the counting rough; a precise log becomes another task to fail at. Pair with activity scheduling where the client is ready for it.', '[{"id": "f0", "type": "textarea", "label": "Daylight minutes today, and where I got them:"}, {"id": "f1", "type": "textarea", "label": "Mood today, 0 to 10, rated at the end of the day:"}, {"id": "f2", "type": "textarea", "label": "The easiest place I could add ten minutes of daylight:"}, {"id": "f3", "type": "textarea", "label": "After two weeks: the pattern I see, if any:"}, {"id": "f4", "type": "textarea", "label": "What I will try for the next two weeks based on my own log:"}]'::jsonb, array['depression', 'self-monitoring', 'behavioral activation']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('everything-takes-forever-time-estimate-check-sheet', 'Everything Takes Forever Time Estimate Check Sheet', 'cbt'::resource_kind, 'A CBT sheet comparing how long a low-mood client predicts a task will take with how long it actually takes.', 'Use it to shrink the imagined size of ordinary tasks that low mood has inflated into impossible ones.', array['Adults', 'Teens']::text[], 'Ten minutes daily for one week', 'Low mood stretches tasks in the mind: the dishes become an hour, the email becomes an afternoon. The sheet asks the client to write a predicted time for a few tasks before starting, then time the real thing. Most predictions are two to five times too long. The debrief is not that the client was wrong; it is that the mood is adding time in advance and the tax is paid before the task begins. Use the findings to pick the next day''s tasks by real minutes, and let the client see how many fit into an hour.', '[{"id": "f0", "type": "textarea", "label": "Tasks I am avoiding, and how long each feels like it will take:"}, {"id": "f1", "type": "textarea", "label": "The real time each took when I did it:"}, {"id": "f2", "type": "textarea", "label": "How many times too long my predictions were:"}, {"id": "f3", "type": "textarea", "label": "What the gap says about how my mood sizes tasks:"}, {"id": "f4", "type": "textarea", "label": "Tomorrow''s tasks, planned by real minutes instead of predicted ones:"}]'::jsonb, array['depression', 'core CBT', 'predictions']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('heavy-coat-of-low-mood-metaphor-page', 'Heavy Coat of Low Mood Metaphor Page', 'act'::resource_kind, 'An ACT page that pictures low mood as a heavy coat the client did not choose, and asks what they can do while wearing it.', 'Use it to shift a client from waiting for the mood to lift to moving, slowly, with the weight still on.', array['Adults', 'Teens']::text[], '20 minutes', 'The coat is heavy, it is hot, and the client did not pick it out. They can stand still until it comes off, or they can walk, slower than usual, to somewhere worth going. The page asks what the coat weighs today, what the client has been waiting to do until it comes off, and what a short walk in the coat would look like. Honor how heavy it is; this is not a pep talk. The committed action that follows is sized to the coat: a shorter walk, a smaller task, done anyway. Return to the metaphor on days the client wants to wait again.', '[{"id": "f0", "type": "textarea", "label": "How heavy the coat is today, and what it feels like to wear:"}, {"id": "f1", "type": "textarea", "label": "What I have been waiting to do until the coat comes off:"}, {"id": "f2", "type": "textarea", "label": "What a short walk in the coat would look like today:"}, {"id": "f3", "type": "textarea", "label": "Where I would want to walk to if the weight were not a reason to stay:"}, {"id": "f4", "type": "textarea", "label": "What I notice about the coat after moving in it, even a little:"}]'::jsonb, array['depression', 'core ACT', 'metaphor']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('mindfulness-of-pleasant-moments-noticing-card', 'Mindfulness of Pleasant Moments Noticing Card', 'dbt'::resource_kind, 'A DBT card for being mindful of positive experiences as they happen: staying in them and refocusing when the mind leaves.', 'Use it to help a client whose mind skips past the good moments stay in one long enough for it to count.', array['Adults', 'Teens']::text[], 'Five minutes daily for two weeks', 'Accumulating positives fails when the client has the experience and misses it. The card has three moves: notice the pleasant moment while it is happening, stay in it with full attention, and refocus when the mind drifts to whether it will last or whether they deserve it. The client records one moment a day and which of the three moves was hardest. Watch for the mind''s exit lines, usually something about it not lasting; name them as exits, not facts. Pair with pleasant activity scheduling so there are moments to practice on.', '[{"id": "f0", "type": "textarea", "label": "Today''s pleasant moment, however small:"}, {"id": "f1", "type": "textarea", "label": "How long I stayed in it before my mind left:"}, {"id": "f2", "type": "textarea", "label": "Where my mind went when it left (will it last, do I deserve it, something else):"}, {"id": "f3", "type": "textarea", "label": "What I did to come back to the moment:"}, {"id": "f4", "type": "textarea", "label": "After two weeks: the exit line my mind uses most, and my reply to it:"}]'::jsonb, array['depression', 'core DBT', 'mindfulness']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('invitations-kept-open-agreement-for-partners', 'Invitations Kept Open Agreement for Partners', 'couples'::resource_kind, 'An agreement for a couple in which one partner''s low mood means declining plans, keeping invitations open without pressure.', 'Use it to help a couple keep connection alive during a low stretch without the well partner nagging or giving up.', array['Couples']::text[], '30 minutes', 'When one partner is in a low stretch, the other often stops asking after a few refusals, and the lonelier partner reads it as being given up on. The agreement sets a different pattern: the inviting partner keeps asking, in a low-key form they agree on, and the other may decline freely; a decline is answered with a plan to ask again, not a sigh. The partner in the low stretch names one invitation they will say yes to this week, sized to the mood. Both write down what the other''s part looks like when it is done well, so it can be recognized.', '[{"id": "f0", "type": "textarea", "label": "Partner in the low stretch: what it is like when invitations stop, and what I want to keep hearing:"}, {"id": "f1", "type": "textarea", "label": "Inviting partner: what it is like to keep asking, and what I need to keep going:"}, {"id": "f2", "type": "textarea", "label": "How invitations will be offered, and how a no will be answered:"}, {"id": "f3", "type": "textarea", "label": "The one invitation this week I will say yes to, sized to how I am:"}, {"id": "f4", "type": "textarea", "label": "What each of us will notice when the other does their part well:"}]'::jsonb, array['depression', 'couples', 'support']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('launch-pad-by-the-door-setup-sheet', 'Launch Pad by the Door Setup Sheet', 'worksheet'::resource_kind, 'A planner for a single spot by the door where keys, wallet, bag and tomorrow''s items land every time.', 'Use it to cut the morning hunt for essentials by giving every item one home a client walks past anyway.', array['Adults', 'Teens']::text[], '20 minutes to plan, one evening to set up', 'The launch pad is a hook, tray or shelf by the exit that holds everything that leaves with the client. The sheet lists what goes missing most, what container or hook each needs, and the evening habit of loading the pad before bed. Clients with attention difficulties often need the pad to be visually loud and in the path of travel, not in a tidy drawer. Expect the pad to fail on the first distracted evening; the fix is making the loading step part of an existing routine, such as plugging in the phone. Review after a week for what still goes missing.', '[{"id": "f0", "type": "textarea", "label": "The things I hunt for most mornings:"}, {"id": "f1", "type": "textarea", "label": "Where my launch pad will be, in my path to the door:"}, {"id": "f2", "type": "textarea", "label": "What hook, tray or bin each item gets:"}, {"id": "f3", "type": "textarea", "label": "The evening routine I will attach the loading step to:"}, {"id": "f4", "type": "textarea", "label": "After a week: what still went missing, and what the pad needs changed:"}]'::jsonb, array['ADHD', 'executive function', 'routines']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('time-estimate-versus-actual-log-sheet', 'Time Estimate Versus Actual Log Sheet', 'cbt'::resource_kind, 'A CBT self-monitoring log of how long a client thinks a task will take, how long it takes, and the pattern in the gap.', 'Use it to give a client with time blindness their own data on which way their estimates run and by how much.', array['Adults', 'Teens']::text[], 'One week of brief entries', 'Time blindness runs both ways: some tasks are wildly underestimated (getting ready takes five minutes) and others inflated (the form will take all day). The log collects both numbers for a week of tasks. Then the client looks for which kinds of task run which way. The adjustment that follows is a personal multiplier for each kind, not a general rule to be more realistic. Clients often find transitions and getting-out-the-door tasks are the ones running short. Keep entries to a few seconds each or the log itself will be abandoned.', '[{"id": "f0", "type": "textarea", "label": "Tasks this week, with my estimate before starting:"}, {"id": "f1", "type": "textarea", "label": "The real time each took:"}, {"id": "f2", "type": "textarea", "label": "The kinds of task I underestimate, and by about how much:"}, {"id": "f3", "type": "textarea", "label": "The kinds of task I overestimate:"}, {"id": "f4", "type": "textarea", "label": "My personal multiplier for each kind, to use when planning next week:"}]'::jsonb, array['ADHD', 'core CBT', 'self-monitoring']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('shiny-new-project-urge-noticing-page', 'Shiny New Project Urge Noticing Page', 'act'::resource_kind, 'An ACT page for the pull of a new project when a current one gets dull, noticing the urge and checking it against values.', 'Use it to help a client notice the pull of the new before it has quietly ended the old, and choose on purpose.', array['Adults', 'Teens']::text[], '15 minutes, then at each urge', 'The urge arrives as excitement and certainty: this is the one. The page asks the client to describe the urge as a body sensation and a set of thoughts, list the half-finished projects it has produced, and check both the new and the old against their values rather than their excitement. Sometimes the new project is the right move; the page is not against novelty. It is for choosing with eyes open. Have the client build a short waiting rule, such as a week in a notebook before any new project gets money or materials, and track what the urge does during the wait.', '[{"id": "f0", "type": "textarea", "label": "What the urge feels like in my body and what it says:"}, {"id": "f1", "type": "textarea", "label": "Projects the urge has started, and where each sits now:"}, {"id": "f2", "type": "textarea", "label": "What the current project is in service of, if anything:"}, {"id": "f3", "type": "textarea", "label": "What the new one would be in service of:"}, {"id": "f4", "type": "textarea", "label": "My waiting rule before a new project gets money, time or materials:"}, {"id": "f5", "type": "textarea", "label": "What the urge did during the wait this time:"}]'::jsonb, array['ADHD', 'core ACT', 'willingness']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('cope-ahead-for-the-long-boring-meeting-card', 'Cope Ahead for the Long Boring Meeting Card', 'dbt'::resource_kind, 'A DBT cope ahead card for sitting through a long, dull meeting or class: the plan, the skills and the rehearsal.', 'Use it to help a client who drifts, fidgets or blurts in long meetings arrive with a rehearsed plan.', array['Adults', 'Teens']::text[], '15 minutes to build, rehearsed the night before', 'Cope ahead means describing the situation, choosing the skills, rehearsing in imagination and then relaxing. For a long meeting the skills are usually a quiet fidget that does not distract others, a note-taking job that keeps the hands busy, a planned stretch break, and a one-line script for when a thought wants out before its turn. The card holds all of it. The rehearsal step matters most and is the one clients skip; do it in session the first time. Debrief afterward on which skill got used and what the drift did when it came.', '[{"id": "f0", "type": "textarea", "label": "The meeting or class, and what usually goes wrong for me in it:"}, {"id": "f1", "type": "textarea", "label": "My quiet fidget and my hands-busy job:"}, {"id": "f2", "type": "textarea", "label": "When I will take a stretch or bathroom break:"}, {"id": "f3", "type": "textarea", "label": "What I will do with a thought that wants out before its turn:"}, {"id": "f4", "type": "textarea", "label": "My rehearsal: how I pictured it going, step by step:"}, {"id": "f5", "type": "textarea", "label": "Afterward: what I used, and what happened when I drifted:"}]'::jsonb, array['ADHD', 'core DBT', 'attention']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('morning-routine-picture-cards-craft', 'Morning Routine Picture Cards Craft', 'kids'::resource_kind, 'A child draws each step of the morning on a card and hangs them in order, flipping each one as it is done.', 'Use it to give a child a morning they can see and run themselves, with a parent who points instead of repeating.', array['Children']::text[], '30 minutes to make, used every morning', 'The child draws one picture per morning step: get dressed, breakfast, teeth, shoes, bag. Punch a hole in each and hang them on a string or hooks in order, at the child''s eye level, where the morning happens. Each card flips over when its step is done. The parent''s job changes from repeating instructions to asking what the next card says. Keep to six or fewer steps and let the child order them. If mornings keep stalling at the same card, that card is the step to split in two or move earlier.', '[{"id": "f0", "type": "textarea", "label": "The steps on my cards, in my order:"}, {"id": "f1", "type": "textarea", "label": "Where my cards hang so I can see them:"}, {"id": "f2", "type": "textarea", "label": "The card I always get stuck on:"}, {"id": "f3", "type": "textarea", "label": "What I did when I finished every card this morning:"}, {"id": "f4", "type": "textarea", "label": "Parent: how the mornings went this week when I pointed to the cards instead of repeating:"}]'::jsonb, array['ADHD', 'children', 'routines']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('payday-and-free-money-urge-plan-sheet', 'Payday and Free Money Urge Plan Sheet', 'worksheet'::resource_kind, 'A plan for the days when money lands, when urges to use substances often climb, covering the hours, the cash and the company.', 'Use it to help a client get a paycheck or windfall through the week without it going to substance use.', array['Adults']::text[], '20 minutes', 'Many clients can name the exact day their urges peak: when money arrives. The sheet asks when and how money lands, what the first hours after it usually look like, and what has helped before. Then it plans: where the money goes within the hour (a bill paid, a transfer to someone trusted, an auto-save), who the client will be with that evening, and what the urge is likely to say. Keep the tone matter-of-fact; this is logistics, not a lecture. Review after the first payday on the plan for what held and what needs changing.', '[{"id": "f0", "type": "textarea", "label": "When money usually lands, and what the first few hours after have looked like:"}, {"id": "f1", "type": "textarea", "label": "Where the money will go within the first hour this time:"}, {"id": "f2", "type": "textarea", "label": "Who I will be with on the evening it lands:"}, {"id": "f3", "type": "textarea", "label": "What the urge will probably say, and my reply:"}, {"id": "f4", "type": "textarea", "label": "After the first payday on this plan: what held, and what needs changing:"}]'::jsonb, array['addiction', 'urges', 'planning']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('one-wont-hurt-thought-record', 'One Won''t Hurt Thought Record', 'cbt'::resource_kind, 'A CBT thought record built for the single permission-giving thought that precedes most returns to substance use.', 'Use it to let a client catch and answer the one won''t hurt thought before it does its work.', array['Adults', 'Teens']::text[], '20 minutes, then at each urge', 'The thought arrives sounding reasonable: one won''t hurt, I''ve earned it, I can handle it now. The record asks for the exact wording, the situation, how believable it was in the moment (0 to 100), the evidence from the client''s own history for and against, and a reply they would accept from a friend. The reply has to be honest about what one has led to before, not a slogan. Have the client keep the completed record on their phone and reread it at the next urge rather than writing a new one from scratch in the heat of it.', '[{"id": "f0", "type": "textarea", "label": "The permission-giving thought, in its exact words:"}, {"id": "f1", "type": "textarea", "label": "Where I was and what was happening when it showed up:"}, {"id": "f2", "type": "textarea", "label": "How believable it felt in the moment, 0 to 100:"}, {"id": "f3", "type": "textarea", "label": "What my own history says about what one has led to:"}, {"id": "f4", "type": "textarea", "label": "A reply I would accept if a friend said it to me:"}, {"id": "f5", "type": "textarea", "label": "How believable the thought is now, 0 to 100:"}]'::jsonb, array['addiction', 'core CBT', 'thought record']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('who-i-am-without-it-self-as-context-page', 'Who I Am Without It Self-as-Context Page', 'act'::resource_kind, 'An ACT page that separates the client who notices from the substance use and its stories, finding the self that was there before.', 'Use it to help a client whose identity has fused with substance use locate the part of them that has been watching all along.', array['Adults', 'Teens']::text[], '30 minutes', 'Clients who have used for years often say they do not know who they are without it. The page asks them to recall the noticing self across their life: who was watching at age ten, at a first job, at a worst night, at a best one. The one who noticed all of it is the same one sitting in the room. Then it lists stories the substance use has told about the client, and asks the noticing self to describe them as stories. Keep the frame gentle; this is about finding a steady place to stand, not about who is to blame.', '[{"id": "f0", "type": "textarea", "label": "Moments across my life, and who was noticing each one:"}, {"id": "f1", "type": "textarea", "label": "What the noticing part of me has stayed the same through:"}, {"id": "f2", "type": "textarea", "label": "Stories my substance use has told about who I am:"}, {"id": "f3", "type": "textarea", "label": "What the noticing self sees when it looks at those stories:"}, {"id": "f4", "type": "textarea", "label": "One thing the noticing self knows about me that the stories leave out:"}]'::jsonb, array['addiction', 'core ACT', 'self-as-context']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('mindful-craving-body-scan-card', 'Mindful Craving Body Scan Card', 'dbt'::resource_kind, 'A DBT mindfulness card that walks the body during an urge, describing the sensations without acting on or arguing with them.', 'Use it to help a client ride out an urge by getting curious about where it lives in the body.', array['Adults', 'Teens']::text[], 'Five minutes, used at each urge', 'The card runs a short scan from feet to head during an urge: where is it, what temperature, what shape, does it move, how does it change over ninety seconds. Only describing, no judging and no fixing. Most clients have never once observed an urge; they have only obeyed or fought it. The card has them record the peak and the fade so they see the urge has a shape and an end. Practice first on a mild urge for something ordinary, such as checking a phone, before using it on a substance urge. Pair with a call or text to a support person if the urge is still climbing after the scan.', '[{"id": "f0", "type": "textarea", "label": "Where the urge lives in my body right now, and its temperature and shape:"}, {"id": "f1", "type": "textarea", "label": "What it does over ninety seconds while I only describe it:"}, {"id": "f2", "type": "textarea", "label": "The judging thoughts that showed up, and what I did with them:"}, {"id": "f3", "type": "textarea", "label": "When it peaked and when it started to fade:"}, {"id": "f4", "type": "textarea", "label": "Who I will call or text if it is still climbing after the scan:"}]'::jsonb, array['addiction', 'core DBT', 'urges', 'mindfulness']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('spot-the-rationalization-card-game', 'Spot the Rationalization Card Game', 'game'::resource_kind, 'A group card game in which players spot the rationalization hidden in short scenarios about substance use and name a reply.', 'Use it to sharpen a group''s ear for the reasonable-sounding thoughts that lead back to substance use.', array['Groups', 'Adults', 'Teens']::text[], '30 minutes', 'Rules: prepare twenty scenario cards, each a short story with one rationalization inside (it''s only a work event; I''ve been so good; I need to sleep). Deal five to each player. On a turn a player reads a card; the first to name the rationalization and give a reply the group accepts takes the card. A reply that shames the character does not count. Most cards win. Final round: players write their own most familiar rationalization on a blank card and the group replies to it. Debrief on which ones were hardest to spot because they sounded most reasonable.', '[{"id": "f0", "type": "textarea", "label": "The rationalizations that were hardest to spot, and why they sounded reasonable:"}, {"id": "f1", "type": "textarea", "label": "The best reply I heard from another player:"}, {"id": "f2", "type": "textarea", "label": "My own most familiar rationalization, which I wrote on a card:"}, {"id": "f3", "type": "textarea", "label": "The reply the group gave to mine:"}, {"id": "f4", "type": "textarea", "label": "What I will say to myself the next time it shows up this week:"}]'::jsonb, array['addiction', 'game', 'group', 'urges']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('anger-hangover-recovery-sheet', 'Anger Hangover Recovery Sheet', 'worksheet'::resource_kind, 'A sheet for the hours after a blow-up: the physical crash, the shame, and the steps that help the client recover and repair.', 'Use it to give a client a plan for the aftermath of anger, so the hangover does not become the next trigger.', array['Adults', 'Teens']::text[], '20 minutes', 'After a big anger episode most clients describe a hangover: shaky, exhausted, ashamed, and primed to snap again. The sheet names what the hangover feels like for this client, how long it tends to last, and what makes it worse, usually replaying the episode or rushing to apologize before the body has settled. Then a short recovery sequence: body first (water, food, movement, rest), then a plain-facts review, then the repair. Clients who skip the body step tend to repair badly and re-ignite. Review the sheet after the next episode.', '[{"id": "f0", "type": "textarea", "label": "What my anger hangover feels like, and how long it usually lasts:"}, {"id": "f1", "type": "textarea", "label": "What I usually do in the hangover that makes it worse:"}, {"id": "f2", "type": "textarea", "label": "Body first: what I will do for my body in the first hour:"}, {"id": "f3", "type": "textarea", "label": "Plain facts: what actually happened, without the replay:"}, {"id": "f4", "type": "textarea", "label": "Repair: what I will say, and when my body will be settled enough to say it:"}]'::jsonb, array['anger management', 'regulation', 'repair']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('they-did-it-on-purpose-intent-check-sheet', 'They Did It on Purpose Intent Check Sheet', 'cbt'::resource_kind, 'A CBT sheet for the hostile intent assumption behind anger, listing other explanations and rating each before reacting.', 'Use it to interrupt a client''s leap from what someone did to why they must have done it.', array['Adults', 'Teens']::text[], '20 minutes', 'Anger escalates fastest when the client is certain the other person meant it. The sheet asks for the behavior in plain description, the intent the client assumed, how sure they were (0 to 100), and then at least four other explanations, from the mundane to the generous. Each gets a likelihood. Then the client re-rates the hostile intent. The exercise does not require believing the other person was innocent; it requires noticing that certainty was built without evidence. Have the client run it on a mild example first, then on a live one between sessions.', '[{"id": "f0", "type": "textarea", "label": "What the person actually did, described plainly:"}, {"id": "f1", "type": "textarea", "label": "The intent I assumed, and how sure I was (0 to 100):"}, {"id": "f2", "type": "textarea", "label": "At least four other explanations, from boring to generous:"}, {"id": "f3", "type": "textarea", "label": "How likely each one is:"}, {"id": "f4", "type": "textarea", "label": "How sure I am of hostile intent now (0 to 100):"}, {"id": "f5", "type": "textarea", "label": "What I will do with the gap between my first certainty and now:"}]'::jsonb, array['anger management', 'core CBT', 'thinking traps']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('righteous-anger-hook-noticing-page', 'Righteous Anger Hook Noticing Page', 'act'::resource_kind, 'An ACT page for the anger that feels justified, noticing how being right hooks the client and what the hook costs.', 'Use it to help a client separate having a point from being pulled around by the feeling of having one.', array['Adults', 'Teens']::text[], '25 minutes', 'Righteous anger is the hardest to work with because the client is often correct. The page does not dispute the point. It asks what the hook of being right feels like, what the client does once hooked (rehearsing, lecturing, keeping score), what that costs them in the relationships and hours that matter, and what they could do with the same point unhooked. Clients find the distinction between the point and the hook freeing when it is not framed as being wrong. Finish with one situation this week where they will make their point without taking the hook.', '[{"id": "f0", "type": "textarea", "label": "A recent anger I was right about:"}, {"id": "f1", "type": "textarea", "label": "What the hook of being right felt like, and what it had me do:"}, {"id": "f2", "type": "textarea", "label": "What being hooked cost me, in time, in the relationship, in how I felt afterward:"}, {"id": "f3", "type": "textarea", "label": "What I could have done with the same point, unhooked:"}, {"id": "f4", "type": "textarea", "label": "One situation this week where I will make my point without taking the hook:"}]'::jsonb, array['anger management', 'core ACT', 'values']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('paired-muscle-relaxation-for-anger-card', 'Paired Muscle Relaxation for Anger Card', 'dbt'::resource_kind, 'A DBT TIPP card pairing a tense-and-release of the whole body with a slow exhale, for the moments anger is rising in the body.', 'Use it to give a client a sixty-second physical release for a rising anger before it reaches the mouth.', array['Adults', 'Teens']::text[], 'Five minutes to learn, one minute to use', 'Paired muscle relaxation tenses the body on an in-breath and lets go on a long out-breath with a cue word, such as relax or down. For anger, teach it with the jaw, fists and shoulders included, since that is where anger loads. Practice in session at calm first, ten rounds, so the pairing is learned. Then the client uses one to three rounds when they notice the early body signs. The card lists their own early signs and their cue word. It is not a substitute for leaving the room when needed, and the card should say when leaving comes first.', '[{"id": "f0", "type": "textarea", "label": "My early body signs that anger is rising:"}, {"id": "f1", "type": "textarea", "label": "My cue word for the out-breath:"}, {"id": "f2", "type": "textarea", "label": "The muscles I load anger into most:"}, {"id": "f3", "type": "textarea", "label": "When I will leave the room first instead of using the card:"}, {"id": "f4", "type": "textarea", "label": "This week''s uses, and what happened in the minute after:"}]'::jsonb, array['anger management', 'core DBT', 'TIPP']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('volume-not-content-feedback-sheet-for-partners', 'Volume Not Content Feedback Sheet for Partners', 'couples'::resource_kind, 'A couples sheet separating how something was said from what was said, so a partner can object to the volume without dismissing the point.', 'Use it to help a couple where one partner''s loudness and the other''s shutdown keep the actual issue from being heard.', array['Couples']::text[], '40 minutes', 'In many couples one partner raises the volume and the other hears only the volume. The sheet gives each partner two columns for a recent argument: what was said (the content) and how it was said (the volume, tone, words chosen). Each writes both for themselves and for the other. Then they compare. The louder partner often finds the content was never heard; the quieter partner often finds they dismissed a fair point because of its delivery. The agreement that follows is specific: a volume the content can be heard at, and a way to flag volume without dismissing content.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what I said in the argument, and how I said it:"}, {"id": "f1", "type": "textarea", "label": "Partner A: what my partner said, and how they said it:"}, {"id": "f2", "type": "textarea", "label": "Partner B: what I said in the argument, and how I said it:"}, {"id": "f3", "type": "textarea", "label": "Partner B: what my partner said, and how they said it:"}, {"id": "f4", "type": "textarea", "label": "The content each of us never got to hear because of the volume:"}, {"id": "f5", "type": "textarea", "label": "Our agreement: how we will flag volume without dismissing the point:"}]'::jsonb, array['anger management', 'couples', 'communication']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('family-accommodation-inventory-sheet', 'Family Accommodation Inventory Sheet', 'worksheet'::resource_kind, 'An inventory of the ways household members take part in a client''s rituals or avoidance, filled in together, with one change chosen.', 'Use it to make visible how much the household has organized itself around the rituals, and pick one small step back.', array['Adults', 'Teens']::text[], '40 minutes', 'Partners and parents accommodate out of love: they answer the reassurance question, wash the item, wait while the ritual finishes, avoid the word. The inventory lists each accommodation, who does it, how often, and what both people fear would happen if it stopped. It is filled in together, without blame; the accommodations made sense at the time. Then one accommodation is chosen to step back from, with a script for the family member and a plan for the client''s distress. Do not start with the biggest one. Review weekly and add the next only when the first has held.', '[{"id": "f0", "type": "textarea", "label": "The ways people in my household take part in my rituals or help me avoid things:"}, {"id": "f1", "type": "textarea", "label": "Who does each, and roughly how often:"}, {"id": "f2", "type": "textarea", "label": "What I fear would happen if each stopped, and what they fear:"}, {"id": "f3", "type": "textarea", "label": "The one accommodation we will step back from first:"}, {"id": "f4", "type": "textarea", "label": "What my family member will say instead, and what I will do with the distress:"}, {"id": "f5", "type": "textarea", "label": "After a week: what held, and what we learned:"}]'::jsonb, array['OCD', 'family', 'support']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('doubt-is-not-evidence-sheet', 'Doubt Is Not Evidence Sheet', 'cbt'::resource_kind, 'A CBT sheet that separates the feeling of doubt from evidence of a problem, applied to a client''s checking and reviewing.', 'Use it to show a client that the doubt they are trying to resolve by checking is a feeling, not a finding.', array['Adults', 'Teens']::text[], '25 minutes', 'After the fifth check the lock is no more locked than after the first, but the doubt is louder. The sheet takes a recent episode and asks for the evidence that existed before the first check, what each additional check added to the evidence, and what each check did to the doubt. Clients see on paper that evidence stayed flat while doubt rose with checking. The reply the sheet builds is a sentence about doubt as a feeling that checking feeds. Use it alongside response delay work; the sheet gives the reason to tolerate the doubt, the delay practice gives the method.', '[{"id": "f0", "type": "textarea", "label": "A recent episode: what I was doubting, and what I did about it:"}, {"id": "f1", "type": "textarea", "label": "The evidence I had before the first check:"}, {"id": "f2", "type": "textarea", "label": "What each additional check added to the evidence:"}, {"id": "f3", "type": "textarea", "label": "What each check did to the doubt:"}, {"id": "f4", "type": "textarea", "label": "A sentence about doubt that I can say the next time it asks me to check:"}]'::jsonb, array['OCD', 'core CBT', 'uncertainty']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('intrusive-thought-as-spam-email-page', 'Intrusive Thought as Spam Email Page', 'act'::resource_kind, 'An ACT defusion page that treats intrusive thoughts as spam: unsolicited, alarming in subject line, not worth opening.', 'Use it to give a client a light way to notice an intrusive thought and leave it unopened.', array['Adults', 'Teens']::text[], '20 minutes', 'Spam is designed to be alarming and urgent, and opening it is what makes it dangerous. The page asks the client to write the subject lines their mind sends most, notice what happens when they open one (reading, replying, forwarding to the ritual), and practice the alternative: see the subject line, label it spam, leave it in the folder. The page tracks a week of unopened messages. Keep the humor gentle; for some clients the content is deeply distressing, and the metaphor is about the handling, never about the thought being silly. Never ask for a detailed description of the thoughts'' content.', '[{"id": "f0", "type": "textarea", "label": "The subject lines my mind sends most often:"}, {"id": "f1", "type": "textarea", "label": "What happens when I open one: what I read, reply to and do:"}, {"id": "f2", "type": "textarea", "label": "This week: messages I labeled spam and left unopened:"}, {"id": "f3", "type": "textarea", "label": "What it was like to leave one unopened, in the first minute and after an hour:"}, {"id": "f4", "type": "textarea", "label": "What the spam folder looked like by the end of the week:"}]'::jsonb, array['OCD', 'core ACT', 'intrusive thoughts', 'defusion']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('radical-acceptance-of-not-knowing-for-sure-card', 'Radical Acceptance of Not Knowing for Sure Card', 'dbt'::resource_kind, 'A DBT radical acceptance card for the uncertainty a client''s rituals are trying to erase, practiced on small unknowns first.', 'Use it to help a client practice accepting a small uncertainty fully, so they can bring the skill to the ones that drive rituals.', array['Adults', 'Teens']::text[], 'Ten minutes daily for two weeks', 'Radical acceptance here is of the not knowing: whether the stove is off, whether the email had a typo, whether the thought means something. The card has the client pick a small daily uncertainty and practice the acceptance statements, the willing hands, the turning of the mind each time it reaches for certainty. Only after a week of small ones does it move to an uncertainty connected to a ritual. Write the acceptance statements in the client''s own words, and watch for the statements being used as a new form of reassurance, repeated to feel sure.', '[{"id": "f0", "type": "textarea", "label": "Today''s small uncertainty I am practicing on:"}, {"id": "f1", "type": "textarea", "label": "My acceptance statements, in my own words:"}, {"id": "f2", "type": "textarea", "label": "How many times I turned my mind back when it reached for certainty:"}, {"id": "f3", "type": "textarea", "label": "What my body did with willing hands and the statements:"}, {"id": "f4", "type": "textarea", "label": "Week two: the uncertainty connected to a ritual I brought the skill to, and what happened:"}]'::jsonb, array['OCD', 'core DBT', 'radical acceptance', 'uncertainty']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('boss-back-talk-bubble-comic-craft', 'Boss Back Talk Bubble Comic Craft', 'kids'::resource_kind, 'A child draws a comic of the bossy worry giving an order and themselves answering back in a speech bubble.', 'Use it to give a child words and a picture for answering the worry that tells them to do things over and over.', array['Children']::text[], '30 minutes', 'Draw a two-panel comic. In the first, the worry character (the child names and draws it) gives one of its orders in a speech bubble. In the second, the child draws themselves answering back; help them find a short line that is theirs, something like I heard you and I am not doing that. Make several strips for different orders. The parent reads the strips with the child at calm times and, when an order comes in real life, asks what the comic version would say. Keep the parent in the role of coach, not enforcer, and let the child choose which order to practice on first.', '[{"id": "f0", "type": "textarea", "label": "My worry character''s name and what it looks like:"}, {"id": "f1", "type": "textarea", "label": "The orders it gives me most, one per comic:"}, {"id": "f2", "type": "textarea", "label": "What I say back in my speech bubble:"}, {"id": "f3", "type": "textarea", "label": "The order I am practicing answering first:"}, {"id": "f4", "type": "textarea", "label": "Parent: a time this week the real order came, and what we did:"}]'::jsonb, array['OCD', 'children', 'externalizing', 'craft']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('haircut-and-salon-chair-panic-plan-sheet', 'Haircut and Salon Chair Panic Plan Sheet', 'worksheet'::resource_kind, 'A plan for sitting in a barber or salon chair, where a cape, a mirror and a stranger''s hands often set off panic.', 'Use it to help a client who has been avoiding haircuts get through one appointment with a plan they built.', array['Adults', 'Teens']::text[], '20 minutes', 'The salon chair combines several panic triggers: being still, being watched in a mirror, a cape around the neck, and no graceful exit mid-cut. The sheet maps which of these is hardest for this client, what they will say to the stylist beforehand (a short sentence is enough), where they will put attention during the cut, and what the panic will probably do at its peak. A first appointment can be a short cut or a trim at a quiet time of day. Debrief on what the panic actually did versus what was predicted.', '[{"id": "f0", "type": "textarea", "label": "Which part of the chair is hardest for me: the stillness, the mirror, the cape, the no exit:"}, {"id": "f1", "type": "textarea", "label": "The short sentence I will say to the stylist before we start:"}, {"id": "f2", "type": "textarea", "label": "Where I will put my attention during the cut:"}, {"id": "f3", "type": "textarea", "label": "What the panic will probably do at its peak, and what I will do then:"}, {"id": "f4", "type": "textarea", "label": "Afterward: what the panic actually did compared with what I predicted:"}]'::jsonb, array['panic attacks', 'exposure', 'planning']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('smartwatch-heart-rate-checking-experiment-sheet', 'Smartwatch Heart Rate Checking Experiment Sheet', 'cbt'::resource_kind, 'A CBT experiment on checking a watch or phone for heart rate during anxiety, comparing checking days with no-checking days.', 'Use it to test whether watching the heart rate number calms a client or feeds the panic cycle.', array['Adults', 'Teens']::text[], 'One week', 'Wearable heart rate numbers have become a new safety behavior. The sheet sets up a within-week experiment: three days checking freely and logging anxiety after each check, three days with the heart rate screen hidden or the watch off, with anxiety logged at set times. Clients predict in advance that no-checking days will be worse. Most find the opposite, or no difference, and the discussion is about what the number was doing for them. For a client with an actual heart condition, agree the plan with their physician first and keep the medical checks separate from the anxiety checks.', '[{"id": "f0", "type": "textarea", "label": "My prediction: how anxious the no-checking days will be compared with the checking days:"}, {"id": "f1", "type": "textarea", "label": "Checking days: how often I checked, and my anxiety after each check:"}, {"id": "f2", "type": "textarea", "label": "No-checking days: my anxiety at the set times:"}, {"id": "f3", "type": "textarea", "label": "What the number was doing for me, and what it cost:"}, {"id": "f4", "type": "textarea", "label": "What I will do with the heart rate screen from here:"}]'::jsonb, array['panic attacks', 'core CBT', 'safety behaviors', 'behavioral experiment']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('panic-passenger-not-driver-page', 'Panic Passenger Not Driver Page', 'act'::resource_kind, 'An ACT page that puts panic in the passenger seat: loud, present, allowed to ride along, but not steering.', 'Use it to help a client keep driving toward what matters with panic in the car rather than pulling over for it.', array['Adults', 'Teens']::text[], '20 minutes', 'The client is driving somewhere worth going. Panic climbs into the passenger seat and shouts about the heart, the breath, the exits. The page asks what panic says from that seat, what the client usually does (pull over, turn around, hand it the wheel), and what it would look like to keep driving with it shouting. Then one real trip this week with panic as passenger. The metaphor also works literally for clients whose panic is about driving. Watch for the client trying to make the passenger be quiet; the practice is in letting it shout and keeping their own hands on the wheel.', '[{"id": "f0", "type": "textarea", "label": "Where I am trying to drive to, in my life, that panic interrupts:"}, {"id": "f1", "type": "textarea", "label": "What panic shouts from the passenger seat:"}, {"id": "f2", "type": "textarea", "label": "What I usually do: pull over, turn around, or hand it the wheel:"}, {"id": "f3", "type": "textarea", "label": "What keeping my hands on the wheel would look like this week:"}, {"id": "f4", "type": "textarea", "label": "My one real trip with panic as passenger, and what happened:"}]'::jsonb, array['panic attacks', 'core ACT', 'metaphor']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('tipp-intense-exercise-for-a-panic-surge-card', 'TIPP Intense Exercise for a Panic Surge Card', 'dbt'::resource_kind, 'A DBT TIPP card using a short burst of intense movement to use up the surge of panic in the body, with a settle plan after.', 'Use it to give a client a way to meet the adrenaline of panic with movement rather than stillness and dread.', array['Adults', 'Teens']::text[], 'Ten minutes to plan, a few minutes to use', 'Panic floods the body with energy for running, and most clients freeze in it. The intense exercise piece of TIPP uses that energy: a brisk two minutes of stairs, jumping jacks, a fast walk around the block, then a slow-down with paced breathing. The card lists what the client can do where panic usually hits them (at work, at home, in a store) and what settle-down follows. Clients afraid that exertion will worsen the panic should try it first in session where you can watch, and anyone with a heart or breathing condition agrees the plan with their physician first.', '[{"id": "f0", "type": "textarea", "label": "Where my panic usually hits, and a two-minute intense movement I could do in each place:"}, {"id": "f1", "type": "textarea", "label": "What I fear will happen if I move hard during panic:"}, {"id": "f2", "type": "textarea", "label": "My settle-down after the movement: breathing, water, where I will sit:"}, {"id": "f3", "type": "textarea", "label": "The first time I tried it: what the panic did during and after:"}, {"id": "f4", "type": "textarea", "label": "What I will do differently next time:"}]'::jsonb, array['panic attacks', 'core DBT', 'TIPP']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('body-alarm-true-or-false-relay-game', 'Body Alarm True or False Relay Game', 'game'::resource_kind, 'A relay game where teams race to sort statements about panic sensations into true and false, then defend their choices.', 'Use it to let a group learn what panic sensations do and do not mean while moving and competing.', array['Groups', 'Teens', 'Adults']::text[], '25 minutes', 'Rules: prepare twenty statements about panic sensations (a racing heart during panic means it is damaged: false; feeling dizzy during panic usually passes within minutes: true). Two teams, two piles across the room. One runner at a time grabs a card, runs it to the true or false pile, and tags the next runner. When the cards are gone, go through the piles; each misplaced card is discussed and costs a point. Debrief on the statements the group argued about most, since those are the beliefs doing the work in their own panic. Keep the statements plain and avoid medical claims beyond the basics.', '[{"id": "f0", "type": "textarea", "label": "The statements our team got wrong, and what we thought:"}, {"id": "f1", "type": "textarea", "label": "The statement I was most surprised by:"}, {"id": "f2", "type": "textarea", "label": "The belief about my own panic that the game poked at:"}, {"id": "f3", "type": "textarea", "label": "One statement I will remember the next time my body alarm goes off:"}, {"id": "f4", "type": "textarea", "label": "What it was like to run while thinking about panic:"}]'::jsonb, array['panic attacks', 'game', 'group', 'psychoeducation']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('sibling-fight-referee-script-sheet', 'Sibling Fight Referee Script Sheet', 'worksheet'::resource_kind, 'A parent script for stepping into a sibling fight without picking a winner: separate, calm, hear both, hand the problem back.', 'Use it to give a parent a repeatable sequence for sibling fights that does not require finding out who started it.', array['Adults']::text[], '25 minutes', 'Parents exhaust themselves investigating who started it. The script skips the investigation: separate the children if anyone is unsafe, help both settle, hear each child''s version for one minute without ruling, then hand the problem back with a question about what they will do about it. The sheet has the parent write their own words for each step and name the point they usually get pulled into judging. Rehearse it in session with the parent playing both children. Review which fights it worked for and which needed a different response, such as a clear rule for hitting.', '[{"id": "f0", "type": "textarea", "label": "The fights that happen most, and where I usually get pulled in:"}, {"id": "f1", "type": "textarea", "label": "Step one, separate and settle: what I will say and do:"}, {"id": "f2", "type": "textarea", "label": "Step two, hear both: how I will keep to one minute each without ruling:"}, {"id": "f3", "type": "textarea", "label": "Step three, hand it back: the question I will ask them:"}, {"id": "f4", "type": "textarea", "label": "The point in a fight where I most want to judge, and what I will do instead:"}, {"id": "f5", "type": "textarea", "label": "After a week: fights it worked for, and fights that needed something else:"}]'::jsonb, array['parenting', 'family', 'conflict']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('if-i-give-in-once-catastrophe-check-sheet', 'If I Give In Once Catastrophe Check Sheet', 'cbt'::resource_kind, 'A CBT sheet for the parent belief that one flexible moment will undo every rule, testing it against what has actually followed.', 'Use it to help a rigid parent tell the difference between a chosen exception and a collapse of the rules.', array['Adults']::text[], '20 minutes', 'Some parents hold every rule at full strength because they believe one exception will end all of them. The sheet asks for the belief in their words, a recent moment they wanted to flex and did not, what they predicted would follow if they had, and times they did flex and what actually followed. The distinction it builds is between a chosen, named exception (tonight is special, tomorrow is back to normal) and giving in under pressure. Plan one chosen exception for the week and record what the child did afterward.', '[{"id": "f0", "type": "textarea", "label": "The belief, in my words: if I give in once, then…"}, {"id": "f1", "type": "textarea", "label": "A recent moment I wanted to flex and did not, and what I predicted would follow:"}, {"id": "f2", "type": "textarea", "label": "Times I have flexed before, and what actually followed:"}, {"id": "f3", "type": "textarea", "label": "The difference between a chosen exception and giving in under pressure:"}, {"id": "f4", "type": "textarea", "label": "One chosen exception I will make this week, and how I will name it to my child:"}, {"id": "f5", "type": "textarea", "label": "What my child did in the days after:"}]'::jsonb, array['parenting', 'core CBT', 'predictions']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('good-enough-parent-defusion-page', 'Good Enough Parent Defusion Page', 'act'::resource_kind, 'An ACT page that catches the perfect parent story and practices letting it run while the client parents well enough in front of it.', 'Use it to loosen the grip of a parent''s impossible standard without arguing about whether it is true.', array['Adults']::text[], '25 minutes', 'The perfect parent story has a voice, a list and a verdict, and it never signs off. The page asks the parent to write out the story''s current list, notice when it is loudest, and practice the defusion line: there is the perfect parent story again. Then it asks what good enough actually looked like this week, in plain acts: fed, heard, held, apologized to. Clients who have never written down the standard are often surprised by its size. Watch for the page turning into a new standard of being good enough; the point is doing what matters with the story still talking.', '[{"id": "f0", "type": "textarea", "label": "The perfect parent story''s current list, written out:"}, {"id": "f1", "type": "textarea", "label": "When the story is loudest in my day:"}, {"id": "f2", "type": "textarea", "label": "My defusion line when I notice it:"}, {"id": "f3", "type": "textarea", "label": "What good enough actually looked like this week, in plain acts:"}, {"id": "f4", "type": "textarea", "label": "What I did with my child today while the story was still talking:"}]'::jsonb, array['parenting', 'core ACT', 'defusion', 'self-compassion']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('give-skill-at-bedtime-card', 'GIVE Skill at Bedtime Card', 'dbt'::resource_kind, 'A DBT GIVE card for the bedtime hour: gentle, interested, validating and easy manner, when a parent is most depleted.', 'Use it to help a parent hold the bedtime routine with warmth at the hour their patience is lowest.', array['Adults']::text[], 'Ten minutes to learn, used nightly', 'Bedtime is where parents are most tired and children most stalling, and the GIVE skill was built for keeping a relationship while holding a line. Gentle: no threats, no sarcasm. Interested: one real question about the child''s day. Validating: naming that stopping play is hard. Easy manner: a light tone, a bit of play in the routine. The card has the parent write their own version of each letter, then the limit they are holding alongside it. Rehearse the last ten minutes of bedtime in session. Debrief on which letter drops first when the parent is exhausted.', '[{"id": "f0", "type": "textarea", "label": "Gentle: what I will not say at bedtime, and what I will say instead:"}, {"id": "f1", "type": "textarea", "label": "Interested: the one real question I will ask:"}, {"id": "f2", "type": "textarea", "label": "Validating: what I will name about how hard stopping is:"}, {"id": "f3", "type": "textarea", "label": "Easy manner: where a bit of lightness fits in our routine:"}, {"id": "f4", "type": "textarea", "label": "The limit I am holding while doing all of this:"}, {"id": "f5", "type": "textarea", "label": "Which letter drops first when I am exhausted, and my plan for it:"}]'::jsonb, array['parenting', 'core DBT', 'interpersonal effectiveness']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('family-highs-and-lows-dinner-cards-craft', 'Family Highs and Lows Dinner Cards Craft', 'kids'::resource_kind, 'A child makes a set of high and low cards the family passes around at dinner, each person sharing one of each.', 'Use it to give a family a daily two-minute ritual where a child hears that grown-ups have low moments too.', array['Children']::text[], '20 minutes to make, two minutes at each dinner', 'The child decorates two cards: a sun or an up arrow for the high of the day and a cloud or a down arrow for the low. At dinner the cards go around the table; whoever holds them shares one high and one low, then passes. Grown-ups go first and share real lows, sized for a child, since the child is learning that hard moments are ordinary and speakable. No fixing of anyone''s low is allowed at the table, only thanks for telling. The parent keeps the ritual short and lets the child skip a turn without comment; most children stop skipping within a week.', '[{"id": "f0", "type": "textarea", "label": "What my high card and my low card look like:"}, {"id": "f1", "type": "textarea", "label": "My high and my low from today:"}, {"id": "f2", "type": "textarea", "label": "A low a grown-up shared that surprised me:"}, {"id": "f3", "type": "textarea", "label": "How it feels when nobody tries to fix my low:"}, {"id": "f4", "type": "textarea", "label": "Parent: how the ritual went this week, and a low I shared that my child remembered:"}]'::jsonb, array['parenting', 'children', 'communication', 'craft']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('leaving-the-house-with-a-newborn-steps-sheet', 'Leaving the House With a Newborn Steps Sheet', 'worksheet'::resource_kind, 'A step plan for a new parent who has stopped leaving home, building from the porch to a short errand with the baby.', 'Use it to help a new parent who feels trapped indoors get out the door in steps sized to a hard week.', array['Adults']::text[], '20 minutes to plan, two weeks to run', 'New parents often stop leaving the house because the first outing went badly and the bag is never ready. The sheet starts small: the porch for ten minutes, a walk to the corner, a coffee shop with a quick exit, a store. Each step has a packed-bag checklist, a time of day when the baby tends to be settled, and a plan for a feed or a cry in public. A step repeats until it feels ordinary. Watch for shame about needing this; most new parents do. The sheet also asks who could come along on the first steps, and whether getting out helps the parent''s mood.', '[{"id": "f0", "type": "textarea", "label": "Why leaving has gotten hard, and what happened last time:"}, {"id": "f1", "type": "textarea", "label": "My steps, from the porch to a short errand:"}, {"id": "f2", "type": "textarea", "label": "The bag checklist, so it is always packed:"}, {"id": "f3", "type": "textarea", "label": "The time of day the baby is usually settled, and my plan for a feed or cry in public:"}, {"id": "f4", "type": "textarea", "label": "Who could come along on the first steps:"}, {"id": "f5", "type": "textarea", "label": "After each outing: how it went, and what it did for my mood:"}]'::jsonb, array['perinatal and postpartum', 'avoidance', 'planning']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('crying-baby-means-i-failed-thought-check-sheet', 'Crying Baby Means I Failed Thought Check Sheet', 'cbt'::resource_kind, 'A CBT thought check for the belief that a crying baby is a verdict on the parent, with evidence from the parent''s own days.', 'Use it to help a new parent separate the baby''s crying from the story that it measures them.', array['Adults']::text[], '20 minutes', 'The thought arrives with the cry: I am doing this wrong, a better parent would know. The sheet asks for the thought in the parent''s words, how believable it is at 3 a.m. versus at noon, what the crying has actually been about in the past week (hunger, tiredness, gas, nothing findable), and what the parent did in response each time. The evidence usually shows a parent responding well to a baby who cries for reasons that are not about them. Build a reply the parent can say over the crying, and keep it short enough to remember while exhausted.', '[{"id": "f0", "type": "textarea", "label": "The thought in my words when the baby cries:"}, {"id": "f1", "type": "textarea", "label": "How believable it is at 3 a.m., and at noon (0 to 100):"}, {"id": "f2", "type": "textarea", "label": "What the crying has actually been about this week, when I could tell:"}, {"id": "f3", "type": "textarea", "label": "What I did each time, listed plainly:"}, {"id": "f4", "type": "textarea", "label": "A short reply I can say over the crying:"}]'::jsonb, array['perinatal and postpartum', 'core CBT', 'self-criticism']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('feeding-choice-values-not-verdict-page', 'Feeding Choice Values Not Verdict Page', 'act'::resource_kind, 'An ACT page that takes the judgment out of how a baby is fed and reconnects the parent''s choice to the values behind it.', 'Use it to help a parent carrying guilt about feeding, however they feed, stand on their values instead of others'' verdicts.', array['Adults']::text[], '25 minutes', 'Feeding is where new parents absorb the most judgment, from strangers, family and their own minds, whatever they chose or had to choose. The page asks for the verdicts the parent has heard and the ones they hand themselves, then sets them beside the values the actual choice serves: a fed baby, a rested parent, a return to work, a body that needed a different plan. The choice is not revisited here; the page is about how the parent holds it. Finish with a sentence that states the choice and the value together. Avoid any discussion of the parent''s body or the baby''s size.', '[{"id": "f0", "type": "textarea", "label": "The verdicts I have heard about how I feed my baby:"}, {"id": "f1", "type": "textarea", "label": "The verdicts I hand myself:"}, {"id": "f2", "type": "textarea", "label": "The values my actual feeding choice serves:"}, {"id": "f3", "type": "textarea", "label": "What it is like to hold the choice as mine rather than as a grade:"}, {"id": "f4", "type": "textarea", "label": "A sentence that states my choice and my value together:"}]'::jsonb, array['perinatal and postpartum', 'core ACT', 'values']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('self-soothe-for-the-middle-of-the-night-feed-card', 'Self-Soothe for the Middle of the Night Feed Card', 'dbt'::resource_kind, 'A DBT self-soothe card for the loneliest feed of the night, with sense-based comforts set up before bed so they are within reach.', 'Use it to make the night feed a little kinder for a parent who dreads the hours when everyone else is asleep.', array['Adults']::text[], 'Ten minutes to set up each evening', 'The night feed is often where the hard thoughts gather. The card has the parent choose one comfort for each sense and stage it before bed: a soft blanket over the chair, a warm drink in a thermos, a quiet playlist or audiobook, a lamp with warm light, a scent on the wrist. During the feed the attention goes to the comforts and the baby, not to the thoughts. The card also names who the parent can text at that hour if the thoughts turn dark, and 988 (call or text) if they ever feel unsafe or hopeless. Review with the parent whether the feeds have shifted at all.', '[{"id": "f0", "type": "textarea", "label": "One comfort for each sense that I will stage before bed:"}, {"id": "f1", "type": "textarea", "label": "Where I will put my attention during the feed:"}, {"id": "f2", "type": "textarea", "label": "The thoughts that tend to gather at that hour:"}, {"id": "f3", "type": "textarea", "label": "Who I can text at that hour, and 988 (call or text) if I ever feel unsafe or hopeless:"}, {"id": "f4", "type": "textarea", "label": "After a week: what the night feeds have been like:"}]'::jsonb, array['perinatal and postpartum', 'core DBT', 'self-soothing', 'safety']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('partner-notice-signs-i-am-struggling-sheet-for-new-parents', 'Partner Notice Signs I Am Struggling Sheet for New Parents', 'couples'::resource_kind, 'A sheet where each new parent lists their own signs of going under and what they want the other to do when they see them.', 'Use it to give a new-parent couple an early warning system for each other, agreed before either is at the bottom.', array['Couples']::text[], '30 minutes', 'By the time a new parent says they are not okay, they have often been not okay for weeks. The sheet asks each partner to list their own early signs (snapping, going quiet, not showering, not eating, doom scrolling at the feed), then what they would want the other to do on seeing them: ask, take the baby, call someone, insist on a nap. Each also lists what not to do. Both agree on a phrase for raising it. Include who the couple will call if either sees signs of the other feeling hopeless or unsafe, with 988 (call or text) on the sheet, and complete that part in session.', '[{"id": "f0", "type": "textarea", "label": "Partner A: my early signs that I am going under:"}, {"id": "f1", "type": "textarea", "label": "Partner A: what I want my partner to do when they see them, and what not to do:"}, {"id": "f2", "type": "textarea", "label": "Partner B: my early signs that I am going under:"}, {"id": "f3", "type": "textarea", "label": "Partner B: what I want my partner to do when they see them, and what not to do:"}, {"id": "f4", "type": "textarea", "label": "Our phrase for raising it without it becoming a fight:"}, {"id": "f5", "type": "textarea", "label": "Who we will call if either of us seems hopeless or unsafe, including 988 (call or text):"}]'::jsonb, array['perinatal and postpartum', 'couples', 'support', 'safety']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('mistakes-i-survived-timeline-sheet', 'Mistakes I Survived Timeline Sheet', 'worksheet'::resource_kind, 'A timeline of mistakes the client has made and lived through, with what followed each one and what the client did next.', 'Use it to show a client who fears any error that their record of surviving mistakes is longer than they think.', array['Adults', 'Teens']::text[], '30 minutes', 'Clients who treat every mistake as fatal have usually never looked at the full record. The timeline asks for mistakes across their life, from small to large, and for each: what they feared would happen, what actually happened, and what they did afterward. The pattern that shows up is survival and often repair, and the client sees their own history of recovery. Keep the tone of the review warm; this is not a list of failings but of landings. Finish with the current mistake they fear most and where it would sit on the timeline.', '[{"id": "f0", "type": "textarea", "label": "Mistakes I remember making, across my life, small and large:"}, {"id": "f1", "type": "textarea", "label": "For each: what I feared would happen:"}, {"id": "f2", "type": "textarea", "label": "What actually happened:"}, {"id": "f3", "type": "textarea", "label": "What I did afterward:"}, {"id": "f4", "type": "textarea", "label": "The mistake I most fear making now, and where it would sit on this timeline:"}, {"id": "f5", "type": "textarea", "label": "What this timeline tells me about my record of surviving mistakes:"}]'::jsonb, array['self-esteem', 'self-compassion', 'evidence']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('their-silence-means-disapproval-check-sheet', 'Their Silence Means Disapproval Check Sheet', 'cbt'::resource_kind, 'A CBT sheet for reading a lack of reply or praise as disapproval, listing the other things silence usually means.', 'Use it to help a client who scans for approval stop filling silences with the worst reading.', array['Adults', 'Teens']::text[], '20 minutes', 'An unanswered text, a boss who said nothing about the report, a friend who did not comment on the photo: the client fills each silence with disapproval. The sheet collects a week of silences, the reading the client gave each, and the eventual explanation where one appeared. It then builds a list of what silence usually means (busy, forgot, did not see, fine with it, nothing) and asks the client to rate how often each applied in their own data. The reply that follows is a sentence to use at the next silence. Pair with asking directly when it matters.', '[{"id": "f0", "type": "textarea", "label": "Silences this week, and the reading I gave each:"}, {"id": "f1", "type": "textarea", "label": "What each silence eventually turned out to mean, where I found out:"}, {"id": "f2", "type": "textarea", "label": "What silence usually means, in my own data:"}, {"id": "f3", "type": "textarea", "label": "A sentence I will say to myself at the next silence:"}, {"id": "f4", "type": "textarea", "label": "One silence this week I will ask about directly instead of reading:"}]'::jsonb, array['self-esteem', 'core CBT', 'mind reading']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('kind-observer-self-as-context-page', 'Kind Observer Self-as-Context Page', 'act'::resource_kind, 'An ACT page that locates the self that has watched every success and failure with the same eyes, and lets that observer be kind.', 'Use it to give a client a place to stand that is not their achievements and not their failures.', array['Adults', 'Teens']::text[], '25 minutes', 'Self-esteem rises and falls with the last thing that happened. The observer does not. The page asks the client to recall being watched by themselves at a proud moment and at a shameful one, and to notice the watcher was the same in both. Then it asks the watcher to describe the client as it would describe anyone it had seen that long: with context, with kindness, without a score. Some clients find the kind observer hard to find and locate a harsh one instead; that is useful, and the page asks who the harsh one learned its tone from. Return to the observer whenever the score swings.', '[{"id": "f0", "type": "textarea", "label": "A proud moment, and who was watching from inside me:"}, {"id": "f1", "type": "textarea", "label": "A shameful moment, and who was watching then:"}, {"id": "f2", "type": "textarea", "label": "What stayed the same about the watcher in both:"}, {"id": "f3", "type": "textarea", "label": "How the watcher would describe me after all it has seen, without a score:"}, {"id": "f4", "type": "textarea", "label": "If the watcher I found was harsh: who it learned that tone from:"}, {"id": "f5", "type": "textarea", "label": "What changes when I stand in the observer rather than in the score:"}]'::jsonb, array['self-esteem', 'core ACT', 'self-as-context']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('nonjudgmental-self-description-sheet', 'Nonjudgmental Self-Description Sheet', 'dbt'::resource_kind, 'A DBT mindfulness sheet that rewrites a client''s judgmental self-descriptions into plain facts, preferences and consequences.', 'Use it to show a client how much of their self-image is judgment rather than description, and practice the swap.', array['Adults', 'Teens']::text[], '25 minutes', 'The nonjudgmental stance applied inward: lazy becomes I left the dishes three days this week; stupid becomes I did not understand the instructions the first time. The sheet takes five of the client''s self-judgments and rewrites each into what happened, what they wanted, and what the consequence was. Clients are often startled by how little is left once the judgment word is removed. The practice for the week is catching one judgment a day and rewriting it on the spot. Keep the rewrites honest; whitewashing is a judgment too.', '[{"id": "f0", "type": "textarea", "label": "Five judgments I make about myself, in the words I use:"}, {"id": "f1", "type": "textarea", "label": "Each one rewritten as what happened, plainly:"}, {"id": "f2", "type": "textarea", "label": "What I wanted in each situation, and what the consequence was:"}, {"id": "f3", "type": "textarea", "label": "What is left of the judgment once the word is gone:"}, {"id": "f4", "type": "textarea", "label": "This week: one judgment a day I caught and rewrote on the spot:"}]'::jsonb, array['self-esteem', 'core DBT', 'mindfulness', 'self-criticism']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('appreciation-web-yarn-toss-game', 'Appreciation Web Yarn Toss Game', 'game'::resource_kind, 'A circle game where a ball of yarn is tossed with a specific appreciation each time, building a visible web that holds the group.', 'Use it to let a group give and receive specific appreciation while building something they can see.', array['Groups', 'Teens', 'Children']::text[], '20 minutes', 'Rules: the first player holds the end of the yarn, names someone across the circle and says one specific thing they appreciate about them (not nice, but you waited for me when I was late), then tosses the ball while keeping hold of the strand. The receiver does the same. Everyone must receive at least once before anyone receives twice. When the ball runs out, the group looks at the web and tests it: if one person drops their strand, what happens? Debrief on what it was like to receive, which is usually harder than giving, and on what the web shows.', '[{"id": "f0", "type": "textarea", "label": "The appreciation I received, in the words that were used:"}, {"id": "f1", "type": "textarea", "label": "What it was like to receive it, honestly:"}, {"id": "f2", "type": "textarea", "label": "The appreciation I gave, and how I made it specific:"}, {"id": "f3", "type": "textarea", "label": "What happened to the web when one strand was dropped:"}, {"id": "f4", "type": "textarea", "label": "One appreciation I will give someone outside this group this week:"}]'::jsonb, array['self-esteem', 'game', 'group', 'appreciation']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('phone-call-i-have-been-avoiding-script-and-debrief-sheet', 'Phone Call I Have Been Avoiding Script and Debrief Sheet', 'worksheet'::resource_kind, 'A sheet for one dreaded phone call: the opening line, the one thing that must be said, what to do with a pause, and the debrief.', 'Use it to get a client through a phone call they have been putting off for weeks, and learn from how it went.', array['Adults', 'Teens']::text[], '15 minutes to prepare, five to debrief', 'For many clients a phone call is harder than a presentation because there is no face to read and no time to edit. The sheet chooses one call, writes the opening line and the single thing that must be said, plans what to do with a pause (breathe; it is their turn), and sets a time to make it, in session if needed. The debrief asks what the other person actually did, how long the dread lasted after dialing, and what the client would tell themselves before the next call. Keep the first call low stakes; a pharmacy or a restaurant works.', '[{"id": "f0", "type": "textarea", "label": "The call I have been avoiding, and for how long:"}, {"id": "f1", "type": "textarea", "label": "My opening line, word for word:"}, {"id": "f2", "type": "textarea", "label": "The one thing I have to say before I hang up:"}, {"id": "f3", "type": "textarea", "label": "What I will do with a pause:"}, {"id": "f4", "type": "textarea", "label": "When I will make it:"}, {"id": "f5", "type": "textarea", "label": "Debrief: what they actually did, how long the dread lasted after dialing, and what I will tell myself next time:"}]'::jsonb, array['social anxiety', 'avoidance', 'exposure']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('awkward-silence-survival-experiment-sheet', 'Awkward Silence Survival Experiment Sheet', 'cbt'::resource_kind, 'A CBT experiment where the client lets a conversational pause run for a few seconds on purpose and records what happens.', 'Use it to test a client''s belief that a silence in conversation is a disaster they must fill.', array['Adults', 'Teens']::text[], 'One week of small trials', 'Clients with social anxiety often talk fast to prevent silence, then judge themselves for talking too much. The experiment reverses it: in a few low-stakes conversations this week, let a pause run for three to five seconds without filling it. Predict what the other person will do and how uncomfortable it will be. Record what actually happened. Most find the other person fills it, or that the pause was shorter than it felt. Debrief on who was counting the seconds, and on what talking-to-fill was costing in the conversations. Practice a pause in session first.', '[{"id": "f0", "type": "textarea", "label": "My prediction: what the other person will do in a five-second pause, and how bad it will feel (0 to 100):"}, {"id": "f1", "type": "textarea", "label": "Trial one: where, how long the pause ran, and what happened:"}, {"id": "f2", "type": "textarea", "label": "Trial two:"}, {"id": "f3", "type": "textarea", "label": "Trial three:"}, {"id": "f4", "type": "textarea", "label": "Who was counting the seconds, and what talking-to-fill has been costing me:"}, {"id": "f5", "type": "textarea", "label": "What I now believe about a pause in conversation:"}]'::jsonb, array['social anxiety', 'core CBT', 'behavioral experiment']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('awkward-is-allowed-willingness-page', 'Awkward Is Allowed Willingness Page', 'act'::resource_kind, 'An ACT willingness page that makes room for awkwardness as the price of showing up, with a weekly list of awkward moments survived.', 'Use it to shift a client''s goal from not being awkward to being willing to be awkward in the service of connection.', array['Adults', 'Teens']::text[], '20 minutes, then weekly', 'The goal of never being awkward is both impossible and expensive: it costs the conversation, the invitation, the second date. The page asks what connection is worth to the client, how much awkwardness they are willing to feel for it this week (on a 0 to 10 willingness scale), and what they would do if awkwardness were simply allowed. Then a running list of awkward moments survived. Clients who collect these begin to find them funny, which is not the goal but a sign the struggle has loosened. Keep the willingness number honest; low is fine to start.', '[{"id": "f0", "type": "textarea", "label": "What connection with people is worth to me, specifically:"}, {"id": "f1", "type": "textarea", "label": "How much awkwardness I am willing to feel for it this week, 0 to 10:"}, {"id": "f2", "type": "textarea", "label": "What I would do this week if awkward were simply allowed:"}, {"id": "f3", "type": "textarea", "label": "Awkward moments I survived this week, listed:"}, {"id": "f4", "type": "textarea", "label": "What I notice about the list as it grows:"}]'::jsonb, array['social anxiety', 'core ACT', 'willingness']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('opposite-action-eye-contact-approach-card', 'Opposite Action Eye Contact Approach Card', 'dbt'::resource_kind, 'A DBT opposite action card for the urge to look down and shrink: eyes up, shoulders back, a brief look and a greeting.', 'Use it to give a client an all-the-way opposite action for the body language of social fear, in small steps.', array['Adults', 'Teens']::text[], 'Ten minutes to learn, used daily', 'Social fear says look down, speak softly, take up less room. Opposite action, done all the way, means eyes up and meeting someone''s for a second, shoulders back, a normal-volume greeting. The card sets a small daily target: three brief eye contacts with a greeting, in places like a store, a hallway or a bus stop. It is about the body, not about having a conversation. The client logs how long the contact lasted and what the other person did. Clients from cultures where extended eye contact is rude adjust the target with you; a brief look and a nod is enough.', '[{"id": "f0", "type": "textarea", "label": "What my body does when social fear shows up:"}, {"id": "f1", "type": "textarea", "label": "The all-the-way opposite: what my eyes, shoulders and voice will do:"}, {"id": "f2", "type": "textarea", "label": "My three daily spots for a brief look and a greeting:"}, {"id": "f3", "type": "textarea", "label": "Today''s three: how long each look lasted, and what the other person did:"}, {"id": "f4", "type": "textarea", "label": "What changed in how I felt after a week of this:"}]'::jsonb, array['social anxiety', 'core DBT', 'opposite action']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('playground-invitation-script-cards-craft', 'Playground Invitation Script Cards Craft', 'kids'::resource_kind, 'A child decorates pocket cards with lines for joining play, such as can I play too, and practices them with a parent before the park.', 'Use it to give a shy child words for the moment of joining in, made and rehearsed at home.', array['Children']::text[], '25 minutes to make, used at each park visit', 'On index cards the child writes or the parent writes for them: Can I play too? What are you playing? I like your game. Each card gets a drawing. In the kitchen, the parent plays a child on the playground and the child practices a card; swap roles so the child hears the lines said to them. At the park the cards stay in a pocket, and the plan is to try one line once; the result does not matter, the trying does. The parent stays within sight but does not join in for the child. Afterward the child picks a sticker for the card they used.', '[{"id": "f0", "type": "textarea", "label": "The lines on my cards, in my words:"}, {"id": "f1", "type": "textarea", "label": "The card I practiced most at home, and who I practiced with:"}, {"id": "f2", "type": "textarea", "label": "The line I tried at the park today:"}, {"id": "f3", "type": "textarea", "label": "What happened after I said it:"}, {"id": "f4", "type": "textarea", "label": "Parent: what I did while my child tried a card, and what we celebrated afterward:"}]'::jsonb, array['social anxiety', 'children', 'social skills', 'craft']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('their-belongings-sorting-pacing-plan-sheet', 'Their Belongings Sorting Pacing Plan Sheet', 'worksheet'::resource_kind, 'A paced plan for going through a loved one''s belongings: which room first, how long per sitting, who is there and where things go.', 'Use it to help a grieving client approach the closet or the boxes at a pace they set, with support in place.', array['Adults']::text[], '25 minutes to plan, weeks to carry out', 'The belongings wait, and the client either cannot start or does it all in one brutal day under pressure from a move or a relative. The sheet sets the client''s own pace: which space first (usually not the most charged), how long each sitting lasts, who sits with them, and the four destinations for each item (keep, give to a specific person, donate, undecided box). The undecided box is allowed and revisited later. Plan what happens after each sitting, since the hours afterward are often hardest. Watch for relatives'' timelines overriding the client''s; help them set a boundary where needed.', '[{"id": "f0", "type": "textarea", "label": "The spaces and boxes that are waiting, and which one I will start with:"}, {"id": "f1", "type": "textarea", "label": "How long each sitting will be, and who will be with me:"}, {"id": "f2", "type": "textarea", "label": "The four places things can go, and who the specific people are:"}, {"id": "f3", "type": "textarea", "label": "What I will do in the hour after each sitting:"}, {"id": "f4", "type": "textarea", "label": "Anyone else''s timeline I am feeling pressure from, and what I will say about my own:"}]'::jsonb, array['grief and loss', 'pacing', 'planning']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('i-should-be-over-it-by-now-timeline-check-sheet', 'I Should Be Over It by Now Timeline Check Sheet', 'cbt'::resource_kind, 'A CBT sheet for the belief that grief has a deadline, examining where the deadline came from and what the client''s own grief has done.', 'Use it to help a client stop grading their grief against a timeline they did not choose.', array['Adults', 'Teens']::text[], '25 minutes', 'The deadline is usually borrowed: a comment from a relative, a return-to-work date, a belief about how long others took. The sheet asks for the deadline in the client''s words, where it came from, what they think will happen if they miss it, and what their grief has actually done over the months (not a straight line, but with waves and stretches of ordinary life). Then it asks what they would say to a friend at the same point. The replacement sentence is about grief having its own shape, not a schedule. Avoid implying grief should be finished at all.', '[{"id": "f0", "type": "textarea", "label": "The deadline I am holding myself to, and where it came from:"}, {"id": "f1", "type": "textarea", "label": "What I believe it means that I have missed it:"}, {"id": "f2", "type": "textarea", "label": "What my grief has actually done over the months, waves and ordinary stretches both:"}, {"id": "f3", "type": "textarea", "label": "What I would say to a friend at this point in their grief:"}, {"id": "f4", "type": "textarea", "label": "A sentence about my grief''s shape that I can replace the deadline with:"}]'::jsonb, array['grief and loss', 'core CBT', 'self-criticism']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('values-they-lived-carried-forward-page', 'Values They Lived Carried Forward Page', 'act'::resource_kind, 'An ACT page that names the values the person who died lived by and chooses one for the client to carry forward in their own actions.', 'Use it to give a grieving client a way to keep the person present through what they stood for, acted on in the client''s own life.', array['Adults', 'Teens']::text[], '25 minutes', 'Ask the client what the person cared about, as shown by how they lived: how they treated a waiter, what they made time for, what they could not let pass. The page turns those into a short list of values and asks which the client already shares and which they admired from a distance. Then one value is chosen and one small act in its service is planned for the week, done in the client''s own way rather than as an imitation. The grief rides along with the act. Watch for a client choosing an act out of obligation rather than value; ask whether the person would have wanted it done that way.', '[{"id": "f0", "type": "textarea", "label": "What they cared about, as I saw it in how they lived:"}, {"id": "f1", "type": "textarea", "label": "The values on that list I already share:"}, {"id": "f2", "type": "textarea", "label": "The ones I admired from a distance:"}, {"id": "f3", "type": "textarea", "label": "The value I will carry forward, and one small act in its service this week:"}, {"id": "f4", "type": "textarea", "label": "What it was like to do it, with the grief riding along:"}]'::jsonb, array['grief and loss', 'core ACT', 'values']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('opposite-action-to-isolation-after-loss-card', 'Opposite Action to Isolation After Loss Card', 'dbt'::resource_kind, 'A DBT opposite action card for the pull to be alone after a loss, with contact sized to grief and chosen in advance.', 'Use it to help a grieving client who is disappearing from people choose small, chosen contact over the default of hiding.', array['Adults', 'Teens']::text[], 'Ten minutes to plan, used weekly', 'Some withdrawal in grief is right and needed. The card is for the point where isolation has stopped serving the client and started feeding the sadness. It asks them to tell those two apart in their own terms, then plans small opposite actions: a text answered, a walk with one person, sitting in a cafe among people with no obligation to talk. Contact is sized to grief, which means short and with an exit. The card logs the before and after. Never push a client toward contact that would require performing being fine; the contact should be with people who can sit with sad.', '[{"id": "f0", "type": "textarea", "label": "How I can tell the alone time that helps from the alone time that is feeding the sadness:"}, {"id": "f1", "type": "textarea", "label": "People who can sit with me sad, without needing me to be fine:"}, {"id": "f2", "type": "textarea", "label": "My small opposite actions this week, each with an exit:"}, {"id": "f3", "type": "textarea", "label": "Before and after each one: how I felt:"}, {"id": "f4", "type": "textarea", "label": "What I will keep from this week, and what was too much:"}]'::jsonb, array['grief and loss', 'core DBT', 'opposite action']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('pregnancy-loss-partner-talk-sheet', 'Pregnancy Loss Partner Talk Sheet', 'couples'::resource_kind, 'A talk sheet for a couple after a miscarriage or stillbirth, where each says what the loss was to them and what they need from the other.', 'Use it to help two partners grieving the same loss differently say so to each other without one grief being ranked above the other.', array['Couples']::text[], 'Full session', 'After a pregnancy loss partners often grieve on different timelines and at different volumes, and each can read the other''s as wrong. The sheet gives each a protected turn: what the loss was to them, what they imagined that is now gone, what they need from the other this month, and what they cannot give right now. The listener only hears. Watch for the partner who did not carry the pregnancy minimizing their grief to make room, and the one who did reading the other''s quiet as not caring. Hold both. If either feels unsafe or hopeless, complete a safety plan with 988 (call or text) in session.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what this loss was to me, and what I imagined that is now gone:"}, {"id": "f1", "type": "textarea", "label": "Partner A: what I need from you this month, and what I cannot give right now:"}, {"id": "f2", "type": "textarea", "label": "Partner B: what this loss was to me, and what I imagined that is now gone:"}, {"id": "f3", "type": "textarea", "label": "Partner B: what I need from you this month, and what I cannot give right now:"}, {"id": "f4", "type": "textarea", "label": "What each of us heard that we had not understood before:"}, {"id": "f5", "type": "textarea", "label": "Who we will each lean on besides each other, and 988 (call or text) if either of us ever feels unsafe or hopeless:"}]'::jsonb, array['grief and loss', 'couples', 'support', 'safety']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('roommate-friction-agreement-sheet', 'Roommate Friction Agreement Sheet', 'worksheet'::resource_kind, 'A sheet for the small recurring frictions of sharing a home with a roommate: noise, dishes, guests, bills, and how to raise each.', 'Use it to help a client turn a stewing roommate situation into a few specific asks and a way to make them.', array['Adults', 'Teens']::text[], '25 minutes', 'Roommate problems rarely get named until they explode. The sheet lists the frictions, sorts them by how much each actually matters, and turns the top two or three into specific requests with a time and a tone. It also asks the client what the roommate would probably list about them, which tends to lower the temperature. Then it plans the conversation: when, where, how to open, and what a fair compromise would look like. Rehearse the opening line in session. Review after the conversation for what was agreed and how the client handled pushback.', '[{"id": "f0", "type": "textarea", "label": "The frictions, listed, and how much each actually matters to me (1 to 5):"}, {"id": "f1", "type": "textarea", "label": "What my roommate would probably list about me:"}, {"id": "f2", "type": "textarea", "label": "My top two or three, each turned into a specific request:"}, {"id": "f3", "type": "textarea", "label": "When and where I will raise them, and my opening line:"}, {"id": "f4", "type": "textarea", "label": "What a fair compromise on each would look like:"}, {"id": "f5", "type": "textarea", "label": "After the conversation: what we agreed, and how I handled any pushback:"}]'::jsonb, array['relationship issues', 'boundaries', 'communication']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('if-they-loved-me-they-would-rule-sheet', 'If They Loved Me They Would Rule Sheet', 'cbt'::resource_kind, 'A CBT sheet that surfaces a client''s unspoken rules for how love should be shown and tests each against how the other person shows it.', 'Use it to help a client see the private rulebook they are grading someone against, and decide which rules to keep, say out loud or drop.', array['Adults', 'Teens']::text[], '25 minutes', 'If they loved me they would text first, remember the date, notice I am upset without being told. The rules are rarely spoken and always graded. The sheet asks the client to finish the sentence as many times as they can, then for each rule: where it came from, whether the other person knows it, and how the other person actually shows care that the rule does not count. The three choices for each rule are keep and say it out loud, keep privately, or drop. Watch for the client discovering the other has rules too, which opens a different conversation.', '[{"id": "f0", "type": "textarea", "label": "If they loved me they would… (as many as I can finish):"}, {"id": "f1", "type": "textarea", "label": "For each rule: where it came from, and whether the other person knows it exists:"}, {"id": "f2", "type": "textarea", "label": "Ways the other person shows care that my rules do not count:"}, {"id": "f3", "type": "textarea", "label": "For each rule: keep and say it, keep privately, or drop:"}, {"id": "f4", "type": "textarea", "label": "The rule I will say out loud this week, and how:"}]'::jsonb, array['relationship issues', 'core CBT', 'core beliefs']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('dear-man-for-a-friend-who-keeps-canceling-card', 'DEAR MAN for a Friend Who Keeps Canceling Card', 'dbt'::resource_kind, 'A DBT DEAR MAN card for raising a pattern of canceled plans with a friend, asking for a change while keeping the friendship.', 'Use it to help a client who is hurt by a flaky friend ask for what they want instead of going quiet or exploding.', array['Adults', 'Teens']::text[], '20 minutes', 'Canceled plans build resentment that usually comes out as distance or a blow-up. DEAR MAN gives a third path. Describe the pattern in facts (three of the last four plans canceled the same day). Express the feeling. Assert the ask (a day''s notice, or a plan that is easier to keep). Reinforce what it would mean for the friendship. Stay Mindful of the ask when the friend explains. Appear confident. Negotiate, perhaps to shorter, lower-key plans. The card has the client write each letter in their words and rehearse it aloud in session. Debrief on what the friend said and whether the ask held.', '[{"id": "f0", "type": "textarea", "label": "Describe: the facts of the pattern, with numbers if I have them:"}, {"id": "f1", "type": "textarea", "label": "Express: how it leaves me feeling:"}, {"id": "f2", "type": "textarea", "label": "Assert: what I am asking for:"}, {"id": "f3", "type": "textarea", "label": "Reinforce: what it would do for our friendship:"}, {"id": "f4", "type": "textarea", "label": "Mindful and confident: how I will stay on the ask when they explain:"}, {"id": "f5", "type": "textarea", "label": "Negotiate: what I could accept instead:"}, {"id": "f6", "type": "textarea", "label": "After the conversation: what they said, and whether the ask held:"}]'::jsonb, array['relationship issues', 'core DBT', 'DEAR MAN']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('flooding-signal-and-twenty-minute-break-agreement', 'Flooding Signal and Twenty Minute Break Agreement', 'couples'::resource_kind, 'A couples agreement for when one partner is flooded: a signal, a break of at least twenty minutes, what each does in it, and the return.', 'Use it to give a couple a way to stop a fight that has gone past hearing, with a guaranteed return so the break is not a walkout.', array['Couples']::text[], '30 minutes', 'When a partner is flooded, the heart is pounding and nothing said will land. The agreement sets a signal either can use without explanation, a break of at least twenty minutes (the body needs that long), what each partner does in the break (something soothing, not rehearsing the argument), and a fixed return time. The return is what makes it an agreement rather than one partner leaving. Have each partner describe what flooding feels like in their body so both can spot it. Rehearse the signal and the return once in session, with a mild topic.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what flooding feels like in my body, and my earliest sign:"}, {"id": "f1", "type": "textarea", "label": "Partner B: what flooding feels like in my body, and my earliest sign:"}, {"id": "f2", "type": "textarea", "label": "Our signal, usable by either without explanation:"}, {"id": "f3", "type": "textarea", "label": "What each of us will do in the twenty minutes instead of rehearsing the argument:"}, {"id": "f4", "type": "textarea", "label": "How we set the return time, and what the first sentence back will be:"}, {"id": "f5", "type": "textarea", "label": "After our first real use: what worked, and what we will change:"}]'::jsonb, array['relationship issues', 'couples', 'de-escalation', 'Gottman']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('build-the-apology-card-draw-game', 'Build the Apology Card Draw Game', 'game'::resource_kind, 'A card game where players draw scenario and ingredient cards and build an apology that includes every ingredient, judged by the group.', 'Use it to teach what a complete apology contains by having players assemble them from parts, fast and out loud.', array['Groups', 'Teens', 'Adults']::text[], '25 minutes', 'Rules: two decks. Scenario cards describe a small wrong (forgot a friend''s event; snapped at a sibling). Ingredient cards name parts of an apology: name what I did, say how it affected you, no but, what I will do differently, ask what you need. On a turn, draw one scenario and three ingredients and deliver the apology in thirty seconds. The group checks off each ingredient; all three present scores a point, and the group names the best line. Final round: a real, small thing from each player''s own week, delivered to the group. Debrief on which ingredient everyone kept dropping.', '[{"id": "f0", "type": "textarea", "label": "The apology I built that scored, and the ingredients it had:"}, {"id": "f1", "type": "textarea", "label": "The ingredient I kept dropping:"}, {"id": "f2", "type": "textarea", "label": "The best apology line I heard from another player:"}, {"id": "f3", "type": "textarea", "label": "The real small thing from my week I built an apology for:"}, {"id": "f4", "type": "textarea", "label": "Who I will actually deliver it to, and when:"}]'::jsonb, array['relationship issues', 'game', 'repair', 'group']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('trigger-warnings-for-shows-and-news-plan-sheet', 'Trigger Warnings for Shows and News Plan Sheet', 'worksheet'::resource_kind, 'A plan for shows, films and news stories that touch on sexual violence: checking ahead, choosing, and recovering if caught off guard.', 'Use it to give a survivor choice over the media that reaches them, without cutting them off from the world.', array['Adults', 'Teens']::text[], '20 minutes', 'Media is where many survivors are ambushed: a plot turn, a headline, a group chat sharing a story. The sheet plans three things: how the client will check ahead when they want to (content advisories, a trusted friend who has seen it), how they will decide what to watch and read on a given day, and what they will do if caught off guard (pause, ground, a text to someone, no obligation to finish). It also asks what they want friends to know about sharing stories with them. The goal is choice, not avoidance of everything; some clients want to watch and simply want to pick the day.', '[{"id": "f0", "type": "textarea", "label": "How I will check ahead when I want to, and who I trust to tell me:"}, {"id": "f1", "type": "textarea", "label": "How I will decide what to take in on a given day:"}, {"id": "f2", "type": "textarea", "label": "What I will do if something catches me off guard:"}, {"id": "f3", "type": "textarea", "label": "What I want my friends and family to know about sharing stories with me:"}, {"id": "f4", "type": "textarea", "label": "Something I chose to watch or read this week on my own terms, and how it went:"}]'::jsonb, array['sexual abuse', 'safety', 'stabilizing']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('i-will-never-trust-anyone-again-prediction-check-sheet', 'I Will Never Trust Anyone Again Prediction Check Sheet', 'cbt'::resource_kind, 'A CBT sheet for the prediction that trust is gone for good, tested against small, current moments of trust the client already has.', 'Use it to help a survivor notice the trust they are already exercising, at the size they choose, without rushing them toward more.', array['Adults', 'Teens']::text[], '25 minutes', 'The prediction is absolute and understandable. The sheet does not argue with it. It asks the client to list the small acts of trust already in their week: telling a therapist anything, letting a friend drive, a coworker holding a confidence. Then it asks what the prediction says about those, and what it would mean to rate trust on a dial rather than a switch. Trust at a two is still trust. The client chooses whether and where to move the dial; the sheet only shows that it has positions. Keep all of this away from the events themselves and focused on current life.', '[{"id": "f0", "type": "textarea", "label": "The prediction, in my words:"}, {"id": "f1", "type": "textarea", "label": "Small acts of trust already in my week, listed:"}, {"id": "f2", "type": "textarea", "label": "What the prediction says about those, and what I think:"}, {"id": "f3", "type": "textarea", "label": "Where my trust dial sits with a few specific people (0 to 10):"}, {"id": "f4", "type": "textarea", "label": "Whether I want to move any dial, and by how much, in my own time:"}]'::jsonb, array['sexual abuse', 'core CBT', 'predictions']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('shame-as-a-passenger-not-a-verdict-page', 'Shame as a Passenger Not a Verdict Page', 'act'::resource_kind, 'An ACT page that treats the shame many survivors carry as a passenger that came along from the event, not a judgment that belongs to them.', 'Use it to help a survivor hold shame with some distance, as something carried rather than something true.', array['Adults', 'Teens']::text[], '25 minutes', 'Shame after abuse is almost universal and almost always misassigned. The page does not try to argue the shame away, which rarely works. It asks the client to describe the shame as a passenger: when it got in, what it says, where in the body it rides. Then it asks whose passenger it would be if it were assigned fairly, which the client answers in a word or not at all. The practice is noticing the passenger speak and continuing to drive. The page never asks for details of what happened; the passenger''s arrival date is enough. Pair with self-compassion work and go slowly.', '[{"id": "f0", "type": "textarea", "label": "When the shame passenger got in, in a word or a date, nothing more:"}, {"id": "f1", "type": "textarea", "label": "What it says, and where it rides in my body:"}, {"id": "f2", "type": "textarea", "label": "Whose passenger it would be if it were assigned fairly:"}, {"id": "f3", "type": "textarea", "label": "A moment this week I noticed it speak and kept driving:"}, {"id": "f4", "type": "textarea", "label": "What I would do more of if I did not stop to argue with it:"}]'::jsonb, array['sexual abuse', 'core ACT', 'defusion', 'stabilizing']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('today-is-date-and-place-orienting-card', 'Today Is Date and Place Orienting Card', 'dbt'::resource_kind, 'A DBT describe-skill card for returning to the present: today''s date, where I am, who is here, what is different from then.', 'Use it to give a survivor a short script that pulls the mind back to now when it has slipped into then.', array['Adults', 'Teens']::text[], 'Five minutes to learn, used as needed', 'Orienting statements are the describe skill pointed at time and place. The card is a fill-in script: today is (date), I am in (place), I am (age), the people here are (names), and what is different from then is (three things). Said aloud or in the head, slowly. Rehearse in session until the client can produce it under mild stress. The what-is-different line is the one that does the work; help the client find three differences that are true and concrete. Keep the card on a phone lock screen. It is a stabilizing tool and asks nothing about what then contained.', '[{"id": "f0", "type": "textarea", "label": "My script: today is… I am in… I am… the people here are…"}, {"id": "f1", "type": "textarea", "label": "Three things that are different now from then, true and concrete:"}, {"id": "f2", "type": "textarea", "label": "How I will say it: aloud, whispered, or in my head:"}, {"id": "f3", "type": "textarea", "label": "A time this week I used it, and how long it took to come back:"}, {"id": "f4", "type": "textarea", "label": "What I did with the first minute after I came back:"}]'::jsonb, array['sexual abuse', 'core DBT', 'grounding', 'stabilizing']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('my-feelings-are-my-alarm-bell-craft', 'My Feelings Are My Alarm Bell Craft', 'kids'::resource_kind, 'A child makes a paper bell and decorates it with the feelings that mean something is not okay, and names the grown-ups to tell.', 'Use it to teach a child that uncomfortable feelings about a person or a touch are a signal to tell, and to practice telling.', array['Children']::text[], '25 minutes', 'Cut a bell shape from card. The child decorates it and, with help, writes or draws the inside feelings that mean something is not okay: tummy ache, wanting to hide, a yucky feeling, a secret that feels heavy. On the back, the child draws the grown-ups they would tell, at home and at school. Practice ringing the bell: the child says I need to tell you something and the parent practices listening calmly, the same response they will use in real life. If a child discloses abuse during this activity, follow your mandated reporting duties and your agency''s steps before the session ends.', '[{"id": "f0", "type": "textarea", "label": "The feelings on my bell that mean something is not okay:"}, {"id": "f1", "type": "textarea", "label": "The grown-ups on the back of my bell, at home and at school:"}, {"id": "f2", "type": "textarea", "label": "What I say when I ring my bell:"}, {"id": "f3", "type": "textarea", "label": "Parent: how I practiced listening calmly when my child rang the bell:"}, {"id": "f4", "type": "textarea", "label": "Parent: where the bell will hang, and when we will practice again:"}]'::jsonb, array['sexual abuse', 'children', 'safety', 'craft']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('coping-skills-under-two-minutes-list', 'Coping Skills Under Two Minutes List', 'worksheet'::resource_kind, 'A list of coping skills a client can finish in under two minutes, sorted by where they can be done, for moments with no time to spare.', 'Use it to give a client skills small enough to use in a hallway, a car or a bathroom stall, where most hard moments happen.', array['Adults', 'Teens']::text[], '20 minutes to build', 'Clients abandon coping skills that need a yoga mat and twenty minutes, because the hard moment comes in a meeting. The list collects only skills that take under two minutes: a long exhale, feet on the floor, cold water on wrists, naming five things, a stretch, a text to one person, a sip of water with attention. Sort them by where they work: at a desk, standing in public, in a car, in a bathroom. Have the client test each one once in a calm moment so it is familiar. Review which ones got used and drop the ones that never did.', '[{"id": "f0", "type": "textarea", "label": "Skills I know that take under two minutes:"}, {"id": "f1", "type": "textarea", "label": "Which ones I can do at a desk, standing in public, in a car, in a bathroom:"}, {"id": "f2", "type": "textarea", "label": "Each one tested once in a calm moment: how it felt:"}, {"id": "f3", "type": "textarea", "label": "This week: the ones I actually used, and where:"}, {"id": "f4", "type": "textarea", "label": "The ones I will drop, and the three I will keep closest:"}]'::jsonb, array['coping skills', 'skills', 'planning']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('distraction-versus-avoidance-sort-sheet', 'Distraction Versus Avoidance Sort Sheet', 'cbt'::resource_kind, 'A CBT sort of a client''s go-to coping moves into distraction that helps them return and avoidance that keeps them from ever returning.', 'Use it to help a client see which of their coping habits are a bridge back to the problem and which are a wall against it.', array['Adults', 'Teens']::text[], '25 minutes', 'The same act can be either: a show to settle down before a hard conversation, or the fifth show so the conversation never happens. The sheet lists the client''s coping moves and, for each, asks the test question: after this, do I return to the thing, or does the thing get further away? Then two columns. Clients usually find a few moves in both columns depending on the day, which is the real finding. Plan how to use the distraction ones with a return built in (a time limit, a next step named before starting), and what the avoidance ones are protecting them from.', '[{"id": "f0", "type": "textarea", "label": "My go-to coping moves, listed honestly:"}, {"id": "f1", "type": "textarea", "label": "For each: after it, do I return to the thing or does it get further away:"}, {"id": "f2", "type": "textarea", "label": "The moves that land in both columns depending on the day:"}, {"id": "f3", "type": "textarea", "label": "How I will use the distraction moves with a return built in:"}, {"id": "f4", "type": "textarea", "label": "What the avoidance moves are protecting me from, and one of them I will test this week:"}]'::jsonb, array['coping skills', 'core CBT', 'avoidance']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('coping-to-feel-better-versus-coping-to-live-better-page', 'Coping to Feel Better Versus Coping to Live Better Page', 'act'::resource_kind, 'An ACT page that sorts a client''s coping by what it serves: feeling better right now, or living the life they want.', 'Use it to show a client that the coping that works best for the next hour is sometimes the coping that costs the next year.', array['Adults', 'Teens']::text[], '25 minutes', 'ACT does not rank coping by how fast it reduces distress; it asks what the coping is in service of. The page takes the client''s coping moves and asks two questions of each: does this help me feel better in the next hour, and does this move me toward the life I want? Some moves get two yeses. Some get a yes and a no, and those are the ones to look at. The page is not against feeling better; it asks the client to choose with both columns visible. Finish with one swap: a feel-better move traded for a live-better move in one situation this week.', '[{"id": "f0", "type": "textarea", "label": "My coping moves, listed:"}, {"id": "f1", "type": "textarea", "label": "For each: does it help me feel better in the next hour?"}, {"id": "f2", "type": "textarea", "label": "For each: does it move me toward the life I want?"}, {"id": "f3", "type": "textarea", "label": "The moves with a yes and a no, and what each is costing:"}, {"id": "f4", "type": "textarea", "label": "One swap I will make this week, and the situation I will make it in:"}]'::jsonb, array['coping skills', 'core ACT', 'workability', 'values']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('distress-tolerance-skill-ladder-by-intensity-sheet', 'Distress Tolerance Skill Ladder by Intensity Sheet', 'dbt'::resource_kind, 'A DBT sheet matching skills to distress levels: what works at a three is different from what works at an eight.', 'Use it to help a client stop reaching for a gentle skill in a crisis, or a crisis skill for a mild irritation.', array['Adults', 'Teens']::text[], '30 minutes', 'Clients often say skills do not work, and the mismatch is usually intensity. A breathing practice at an eight is a cup of water on a bonfire; cold water and intense exercise at a three is overkill. The ladder has the client rate their own distress scale with examples at each level, then place skills on it: what works at two to four, at five to seven, at eight and above. TIPP skills belong near the top, mindfulness and self-soothe lower, with overlap. Review after a week of real use and move skills up or down based on what happened, not on what the sheet said.', '[{"id": "f0", "type": "textarea", "label": "My distress scale, with a real example of what each level feels like:"}, {"id": "f1", "type": "textarea", "label": "Skills that work for me at two to four:"}, {"id": "f2", "type": "textarea", "label": "Skills for five to seven:"}, {"id": "f3", "type": "textarea", "label": "Skills for eight and above:"}, {"id": "f4", "type": "textarea", "label": "This week: what level I was at, which skill I reached for, and whether they matched:"}, {"id": "f5", "type": "textarea", "label": "Skills I will move up or down the ladder after this week:"}]'::jsonb, array['coping skills', 'core DBT', 'distress tolerance']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('coping-skill-relay-race-game', 'Coping Skill Relay Race Game', 'game'::resource_kind, 'A relay where each runner reaches a station, draws a scenario, performs a fitting coping skill for the group, and runs back.', 'Use it to get a group practicing skills with their bodies, under a little time pressure, and judging fit together.', array['Groups', 'Children', 'Teens']::text[], '25 minutes', 'Rules: two teams, a station across the room with a bowl of scenario cards (left out of a game; a test tomorrow; a sibling took my thing). A runner reaches the station, draws a card, reads it aloud, and performs a coping skill that fits, in full: a real slow breath, a real stretch, a real self-talk line said out loud. The team calls fit or no fit; a fit scores and the runner tags the next. No fit means the team suggests one and the runner does it before tagging. Debrief on which scenarios were hardest to match and which skills got used most.', '[{"id": "f0", "type": "textarea", "label": "The scenario I drew, and the skill I performed:"}, {"id": "f1", "type": "textarea", "label": "Whether my team called it a fit, and what they suggested if not:"}, {"id": "f2", "type": "textarea", "label": "The skills our team used most:"}, {"id": "f3", "type": "textarea", "label": "The scenario that was hardest to match a skill to:"}, {"id": "f4", "type": "textarea", "label": "A skill from the relay I will use for real this week:"}]'::jsonb, array['coping skills', 'game', 'group', 'skills']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('mri-scanner-fear-preparation-sheet', 'MRI Scanner Fear Preparation Sheet', 'worksheet'::resource_kind, 'A preparation sheet for an MRI or similar scan: what will happen, what the client can control, a plan for the minutes inside, and a debrief.', 'Use it to help a client who has canceled a scan from fear get through one with the parts they can control in hand.', array['Adults', 'Teens']::text[], '25 minutes', 'Canceled scans have real medical costs, so this sheet is practical. It walks through what the client knows about the scan, what they can ask for (music, a mirror, an open or wide-bore machine, a call button, a companion in the room where allowed, eyes closed before going in), and what they will do with attention during the minutes inside. The noise and the stillness are rehearsed in session with eyes closed and a loud recording. A plan for the first sign of panic is written down. Debrief afterward on what the fear predicted and what the minutes actually held.', '[{"id": "f0", "type": "textarea", "label": "What I know about the scan and what I still want to ask the staff:"}, {"id": "f1", "type": "textarea", "label": "What I can ask for, and what I will ask for:"}, {"id": "f2", "type": "textarea", "label": "Where I will put my attention inside, minute by minute:"}, {"id": "f3", "type": "textarea", "label": "What I will do at the first sign of panic:"}, {"id": "f4", "type": "textarea", "label": "My rehearsal in session: what the noise and stillness were like with eyes closed:"}, {"id": "f5", "type": "textarea", "label": "Afterward: what the fear predicted and what the minutes actually held:"}]'::jsonb, array['phobias', 'exposure', 'planning']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('turbulence-facts-versus-fear-sheet', 'Turbulence Facts Versus Fear Sheet', 'cbt'::resource_kind, 'A CBT sheet for the fear of flying that focuses on turbulence: what the fear says is happening, what the client knows, and what to do in it.', 'Use it to give a flying-fearful client a plain account of turbulence to set beside what their fear says about it.', array['Adults', 'Teens']::text[], '25 minutes', 'Most fear of flying peaks in turbulence, and most fear statements about turbulence are about the plane coming apart or falling. The sheet asks for the fear''s account in the client''s words, then what the client already knows or can learn from plain sources: that turbulence is uncomfortable rather than dangerous to the aircraft, that pilots route around the worst of it, that the seat belt is for the bumps. Keep to facts the client can verify, not reassurance. Then a plan for the minutes of bumps: feet flat, a long exhale, a phrase, a task for the hands. Review after the next flight.', '[{"id": "f0", "type": "textarea", "label": "What my fear says is happening during turbulence:"}, {"id": "f1", "type": "textarea", "label": "What I know, or can check in a plain source, about what is actually happening:"}, {"id": "f2", "type": "textarea", "label": "The fear statements that lose the most power against the facts:"}, {"id": "f3", "type": "textarea", "label": "My plan for the minutes of bumps: body, breath, phrase, hands:"}, {"id": "f4", "type": "textarea", "label": "After the flight: how many minutes of bumps there were, and what I did in them:"}]'::jsonb, array['phobias', 'core CBT', 'psychoeducation']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('values-on-the-other-side-of-the-fear-page', 'Values on the Other Side of the Fear Page', 'act'::resource_kind, 'An ACT page that names what waits on the far side of a specific fear and asks what the client is willing to feel to get there.', 'Use it to give a client a reason to approach a feared thing that is theirs, not the therapist''s.', array['Adults', 'Teens']::text[], '20 minutes', 'Exposure fails when the client is doing it to please someone or to be rid of the fear. The page starts on the far side: what is over there? A road trip across a bridge, a garden with bees in it, a dog-owning friend''s house, a dentist''s chair and the teeth that follow. Then it asks what the fear will do on the way, and what the client is willing to feel for the thing on the far side, on a 0 to 10 willingness scale. The step that follows is sized to the willingness, not to the fear. Return to the page before each step so the reason stays in view.', '[{"id": "f0", "type": "textarea", "label": "The feared thing, and what is on the other side of it that I want:"}, {"id": "f1", "type": "textarea", "label": "What the fear will do on the way across, as best I can predict:"}, {"id": "f2", "type": "textarea", "label": "How willing I am to feel that for what is on the other side, 0 to 10:"}, {"id": "f3", "type": "textarea", "label": "The step I will take this week, sized to my willingness:"}, {"id": "f4", "type": "textarea", "label": "After the step: whether the thing on the other side was what I thought:"}]'::jsonb, array['phobias', 'core ACT', 'willingness']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('self-soothe-after-an-exposure-step-card', 'Self-Soothe After an Exposure Step Card', 'dbt'::resource_kind, 'A DBT self-soothe card for the hour after a hard approach step, so the client recovers on purpose instead of crashing.', 'Use it to help a client who does brave things and then falls apart afterward plan a kind recovery that keeps them coming back.', array['Adults', 'Teens']::text[], 'Ten minutes to plan, used after each step', 'Clients who do the exposure step and then spend the evening shaky and ashamed often quit. The card plans the hour after: one thing for each sense, a person to tell, and a line about what was just done, said without minimizing. It is not a reward for success, since the step counts whether the fear dropped or not; it is recovery. Clients sometimes resist, saying they do not deserve comfort for something easy for others. Treat that as part of the work. The card also notes what the body does in the hour after and how long it takes to settle.', '[{"id": "f0", "type": "textarea", "label": "The step I just took, said without minimizing:"}, {"id": "f1", "type": "textarea", "label": "One thing for each sense in the hour after:"}, {"id": "f2", "type": "textarea", "label": "The person I will tell, and what I will say:"}, {"id": "f3", "type": "textarea", "label": "What my body did in the hour after, and how long it took to settle:"}, {"id": "f4", "type": "textarea", "label": "What I will say to the thought that I do not deserve comfort for this:"}]'::jsonb, array['phobias', 'core DBT', 'self-soothing']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('vacuum-cleaner-brave-steps-play', 'Vacuum Cleaner Brave Steps Play', 'kids'::resource_kind, 'A child and parent approach a feared loud appliance in play steps: drawing it, naming it, touching it off, then hearing it from nearer.', 'Use it to help a young child who panics at the vacuum or hand dryer get closer in steps that stay a game.', array['Children']::text[], '15 minutes a day for one to two weeks', 'Loud appliances are a common early fear, and a parent either hides the vacuum or forces the issue. The play steps are small: draw the vacuum and give it a silly name; touch it while it is off; sit in the next room while it runs for ten seconds; sit in the doorway; help push it while it runs. Each step repeats until the child is bored of it. The parent goes at the child''s pace and lets the child say stop, which is always honored, and praises the trying, not the bravery. Ear muffs are fine at early steps and dropped later. Keep notes on how many days each step took.', '[{"id": "f0", "type": "textarea", "label": "The silly name I gave the vacuum and what I drew:"}, {"id": "f1", "type": "textarea", "label": "The step I am on, and how many times I have done it:"}, {"id": "f2", "type": "textarea", "label": "What my body did when it turned on, and what I did next:"}, {"id": "f3", "type": "textarea", "label": "The step I want to try next:"}, {"id": "f4", "type": "textarea", "label": "Parent: how I kept it a game, and the days each step took:"}]'::jsonb, array['phobias', 'children', 'exposure', 'play']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('mirror-free-morning-plan-sheet', 'Mirror-Free Morning Plan Sheet', 'worksheet'::resource_kind, 'A plan for a morning with as little mirror time as possible: what gets covered, what gets timed, and what to do with the minutes saved.', 'Use it to help a client whose mornings are lost to the mirror reclaim the time and see what the checking was doing.', array['Adults', 'Teens']::text[], '20 minutes to plan, one week to try', 'The mirror is often the first and longest appointment of a client''s morning. The sheet maps current mirror minutes, then plans a week with the mirror used only for function (teeth, a quick check of clothes) and timed. Covering the full-length mirror for the week is allowed as an experiment, not a rule. The minutes saved go to something named in advance. Debrief on what the mind did without the mirror, how the day went compared with heavy-checking days, and what the checking had promised to deliver. Never discuss what the client sees in the mirror; the sheet is about the time and the habit.', '[{"id": "f0", "type": "textarea", "label": "How many mirror minutes my morning has now, roughly, and where they go:"}, {"id": "f1", "type": "textarea", "label": "What the mirror is for this week, and the time limit for each use:"}, {"id": "f2", "type": "textarea", "label": "Whether I will cover a mirror, and which one:"}, {"id": "f3", "type": "textarea", "label": "What I will do with the minutes I save:"}, {"id": "f4", "type": "textarea", "label": "After a week: what my mind did without the mirror, and how the days compared:"}]'::jsonb, array['body image', 'habits', 'routines']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('everyone-is-staring-at-me-spotlight-experiment-sheet', 'Everyone Is Staring at Me Spotlight Experiment Sheet', 'cbt'::resource_kind, 'A CBT experiment where the client counts how many people actually look at them in a public place, against the number the belief predicts.', 'Use it to test a client''s sense that their appearance draws every eye in the room.', array['Adults', 'Teens']::text[], 'One outing, plus 20 minutes to plan and debrief', 'The belief is that everyone is looking. The experiment is to count. The client picks a public place, predicts what share of people will look at them and for how long, then spends fifteen minutes observing with a discreet tally: how many people pass, how many glance, how many look for more than a second. Most tallies come in far below the prediction, and the few looks are brief. Debrief on who the client was watching in order to count, usually everyone but themselves, and on how the body felt when attention went outward. Keep the content on the counting, not on the client''s appearance.', '[{"id": "f0", "type": "textarea", "label": "My prediction: what share of people will look at me, and for how long:"}, {"id": "f1", "type": "textarea", "label": "The place, and how long I observed:"}, {"id": "f2", "type": "textarea", "label": "My tally: people who passed, people who glanced, people who looked longer than a second:"}, {"id": "f3", "type": "textarea", "label": "What happened to my attention while I was counting:"}, {"id": "f4", "type": "textarea", "label": "What I now think the spotlight is made of:"}]'::jsonb, array['body image', 'core CBT', 'behavioral experiment']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('body-as-vehicle-not-ornament-page', 'Body as Vehicle Not Ornament Page', 'act'::resource_kind, 'An ACT values page that reframes the body as the vehicle for a client''s life and asks what the vehicle has carried them to.', 'Use it to move a client''s relationship with their body from how it looks to what it does in a life they value.', array['Adults', 'Teens']::text[], '25 minutes', 'A vehicle is judged by where it takes you; an ornament by how it looks on a shelf. The page asks the client to list what their body has carried them to this year: a conversation, a walk, a hug, a job, a laugh until it hurt. Then where they want it to carry them next. Appearance thoughts are allowed to ride along and noted as passengers. The page never asks the client to like their body or to describe it; it asks what it is for. Clients often find the list long and the ornament questions quieter afterward. Avoid any talk of changing the vehicle.', '[{"id": "f0", "type": "textarea", "label": "Places and moments my body has carried me to this year:"}, {"id": "f1", "type": "textarea", "label": "What my body did today that had nothing to do with how it looked:"}, {"id": "f2", "type": "textarea", "label": "Where I want it to carry me next:"}, {"id": "f3", "type": "textarea", "label": "The appearance thoughts that rode along while I wrote this:"}, {"id": "f4", "type": "textarea", "label": "One thing I will do this week that treats my body as a vehicle:"}]'::jsonb, array['body image', 'core ACT', 'values']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('opposite-action-to-hiding-under-layers-card', 'Opposite Action to Hiding Under Layers Card', 'dbt'::resource_kind, 'A DBT opposite action card for dressing to hide, with a small step toward dressing for comfort and the day, chosen by the client.', 'Use it to help a client whose clothes are chosen to disappear take one chosen step the other way.', array['Adults', 'Teens']::text[], 'Ten minutes to plan, used on chosen days', 'Hiding has its own costs: overheating in summer, missing the swim, never wearing the thing they like. Opposite action here is not dressing to be seen; it is dressing for the day and for comfort, with the hiding urge noticed and not obeyed. The card has the client name the hiding moves (the extra layer, the oversized jacket in heat, the arms always crossed), then plan one small opposite on a chosen day: a short sleeve, the jacket left at home, hands at their sides. Log the urge before and the feeling after. Never discuss the body under the clothes; the card is about the moves.', '[{"id": "f0", "type": "textarea", "label": "My hiding moves, listed:"}, {"id": "f1", "type": "textarea", "label": "What the hiding costs me, in comfort and in things I skip:"}, {"id": "f2", "type": "textarea", "label": "My one small opposite action, and the day I will do it:"}, {"id": "f3", "type": "textarea", "label": "The urge before, 0 to 10, and how I felt an hour in:"}, {"id": "f4", "type": "textarea", "label": "What I will try next, if anything, in my own time:"}]'::jsonb, array['body image', 'core DBT', 'opposite action']::text[], '2026-11-15T15:00:00+00:00'::timestamptz),
  ('appearance-reassurance-requests-agreement-for-partners', 'Appearance Reassurance Requests Agreement for Partners', 'couples'::resource_kind, 'A couples agreement on the do I look okay question: what the asking partner needs, and a reply that gives it without feeding the loop.', 'Use it to help a couple replace a reassurance loop about appearance with a response that works for both of them.', array['Couples']::text[], '40 minutes', 'One partner asks do I look okay several times a day; the other says yes and watches it not land. The agreement starts with both partners naming what the question is actually asking for (usually not an appearance verdict but closeness or calm before leaving the house) and what the reassurance has been doing over time. Then they design a reply: an answer the asked partner can give that offers warmth and does not grade the body, and a signal the asking partner can use when they notice the loop starting. Keep the conversation off the body entirely; it is about the pattern.', '[{"id": "f0", "type": "textarea", "label": "Asking partner: what I am actually asking for when I ask if I look okay:"}, {"id": "f1", "type": "textarea", "label": "Answering partner: what it is like to answer, and what I notice the answer does over time:"}, {"id": "f2", "type": "textarea", "label": "Together: what the reassurance has been doing to the pattern:"}, {"id": "f3", "type": "textarea", "label": "The reply we will use that offers warmth and does not grade anything:"}, {"id": "f4", "type": "textarea", "label": "The signal the asking partner can use when they notice the loop starting:"}, {"id": "f5", "type": "textarea", "label": "After a week: how often the question came up, and what our new reply did:"}]'::jsonb, array['body image', 'couples', 'support']::text[], '2026-11-15T15:00:00+00:00'::timestamptz)
